  /* ═══════════════════════════════════════
     本地图片管理（localStorage + FileReader）
     ═══════════════════════════════════════ */
  const IMG_KEYS = { wallpaper: 'av-img-wp' };
  function _getImg(k) { try { return localStorage.getItem(IMG_KEYS[k]) || ''; } catch (e) { return ''; } }
  function _setImg(k, v) { try { localStorage.setItem(IMG_KEYS[k], v); } catch (e) { } }
  function _clearImg(k) { try { localStorage.removeItem(IMG_KEYS[k]); } catch (e) { } }
  function _resizeAndStore(k, dataUrl, maxW, maxH, cb) {
    const img = new Image();
    img.onload = function () {
      let w = img.width, h = img.height;
      if (w > maxW || h > maxH) { const r = Math.min(maxW / w, maxH / h); w = Math.round(w * r); h = Math.round(h * r); }
      const c = document.createElement('canvas'); c.width = w; c.height = h;
      c.getContext('2d').drawImage(img, 0, 0, w, h);
      const out = c.toDataURL('image/jpeg', 0.75);
      _setImg(k, out);
      if (cb) cb(out);
    };
    img.src = dataUrl;
  }
  function _pickImage(k, maxW, maxH, cb) {
    const inp = document.createElement('input');
    inp.type = 'file'; inp.accept = 'image/*';
    inp.onchange = function () {
      const f = this.files[0]; if (!f) return;
      const rd = new FileReader();
      rd.onload = function (e) { _resizeAndStore(k, e.target.result, maxW, maxH, cb); };
      rd.readAsDataURL(f);
    };
    inp.click();
  }
  function _getWallpaper() { return _getImg('wallpaper') || USER_CONFIG.wallpaper || ''; }

  /* 播放器颜色自定义 */
  const PLAYER_COLOR_KEY = 'av-player-color';
  function _getPlayerColor() { try { return localStorage.getItem(PLAYER_COLOR_KEY) || USER_CONFIG.playerColor || ''; } catch (e) { return USER_CONFIG.playerColor || ''; } }
  function _setPlayerColor(c) { try { localStorage.setItem(PLAYER_COLOR_KEY, c); } catch (e) { } }

  /* 主页头像自定义（本地导入） */
  const HOME_AVATAR_KEY = 'av-img-home-avatar';
  function _getHomeAvatar() { try { return localStorage.getItem(HOME_AVATAR_KEY) || USER_CONFIG.homeAvatar || ''; } catch (e) { return USER_CONFIG.homeAvatar || ''; } }
  function _clearHomeAvatar() { try { localStorage.removeItem(HOME_AVATAR_KEY); } catch (e) { } }
  function _pickHomeAvatar(cb) {
    const inp = document.createElement('input');
    inp.type = 'file'; inp.accept = 'image/*';
    inp.onchange = function () {
      const f = this.files[0]; if (!f) return;
      const rd = new FileReader();
      rd.onload = function (e) {
        const img2 = new Image();
        img2.onload = function () {
          let w = img2.width, h = img2.height;
          const mx = 200;
          if (w > mx || h > mx) { const r2 = Math.min(mx / w, mx / h); w = Math.round(w * r2); h = Math.round(h * r2); }
          const cv = document.createElement('canvas'); cv.width = w; cv.height = h;
          cv.getContext('2d').drawImage(img2, 0, 0, w, h);
          const out = cv.toDataURL('image/jpeg', 0.75);
          try { localStorage.setItem(HOME_AVATAR_KEY, out); } catch (x) { }
          if (cb) cb(out);
        };
        img2.src = e.target.result;
      };
      rd.readAsDataURL(f);
    };
    inp.click();
  }

  /* 艺人头像管理 */
  const ACTOR_AVT_PREFIX = 'av-img-actor-';
  function _getActorAvatar(name) { try { return localStorage.getItem(ACTOR_AVT_PREFIX + name) || ''; } catch (e) { return ''; } }
  function _setActorAvatar(name, dataUrl) { try { localStorage.setItem(ACTOR_AVT_PREFIX + name, dataUrl); } catch (e) { } }
  function _clearActorAvatar(name) { try { localStorage.removeItem(ACTOR_AVT_PREFIX + name); } catch (e) { } }
  /* ═══ 玩家立绘管理 ═══ */
  const PLAYER_PORTRAIT_KEY = 'av-player-portrait';        /* 当前选中的内置立绘名 */
  const PLAYER_PORTRAIT_CUSTOM_KEY = 'av-player-portrait-custom';  /* 自定义导入的立绘 dataURL */

  /* 获取玩家性别对应的立绘组 */
  function _getPlayerPortraitGroup() {
    var gender = _getPlayerGender() || '女';  /* 默认女 */
    var arr = USER_CONFIG.playerPortraits || {};
    return arr[gender] || arr['女'] || arr['男'] || {};
  }

  /* 获取当前玩家立绘 URL */
  function _getPlayerPortrait() {
    /* 优先自定义导入 */
    try {
      var custom = localStorage.getItem(PLAYER_PORTRAIT_CUSTOM_KEY);
      if (custom) return custom;
    } catch (e) { }
    /* 其次内置选择 */
    var selected = '';
    try { selected = localStorage.getItem(PLAYER_PORTRAIT_KEY) || ''; } catch (e) { }
    if (!selected) selected = USER_CONFIG.playerPortraitDefault || '立绘1';
    var group = _getPlayerPortraitGroup();
    return group[selected] || '';
  }

  /* 获取当前玩家立绘的名字（用于 UI 显示） */
  function _getPlayerPortraitName() {
    try {
      var custom = localStorage.getItem(PLAYER_PORTRAIT_CUSTOM_KEY);
      if (custom) return '（自定义）';
    } catch (e) { }
    var selected = '';
    try { selected = localStorage.getItem(PLAYER_PORTRAIT_KEY) || ''; } catch (e) { }
    if (!selected) selected = USER_CONFIG.playerPortraitDefault || '立绘1';
    return selected;
  }

  /* 设置内置立绘 */
  function _setPlayerPortrait(name) {
    try { localStorage.setItem(PLAYER_PORTRAIT_KEY, name); } catch (e) { }
    /* 选了内置立绘，清掉自定义 */
    try { localStorage.removeItem(PLAYER_PORTRAIT_CUSTOM_KEY); } catch (e) { }
  }

  /* 清除自定义立绘 */
  function _clearPlayerPortraitCustom() {
    try { localStorage.removeItem(PLAYER_PORTRAIT_CUSTOM_KEY); } catch (e) { }
  }

  /* 导入自定义立绘（压缩到 1664x2496 内） */
  function _pickPlayerPortraitCustom(cb) {
    var inp = document.createElement('input');
    inp.type = 'file'; inp.accept = 'image/*';
    inp.onchange = function () {
      var f = this.files[0]; if (!f) return;
      var rd = new FileReader();
      rd.onload = function (e) {
        var img2 = new Image();
        img2.onload = function () {
          var w = img2.width, h = img2.height;
          var maxW = 1664, maxH = 2496;
          if (w > maxW || h > maxH) {
            var r = Math.min(maxW / w, maxH / h);
            w = Math.round(w * r); h = Math.round(h * r);
          }
          var cv = document.createElement('canvas'); cv.width = w; cv.height = h;
          cv.getContext('2d').drawImage(img2, 0, 0, w, h);
          var out = cv.toDataURL('image/jpeg', 0.82);
          try { localStorage.setItem(PLAYER_PORTRAIT_CUSTOM_KEY, out); } catch (x) {
            if (typeof triggerSlash === 'function') triggerSlash('/echo severity=error 立绘图片过大，存储失败');
          }
          if (cb) cb(out);
        };
        img2.src = e.target.result;
      };
      rd.readAsDataURL(f);
    };
    inp.click();
  }

  /* 判断某个说话人是不是玩家 */
  function _isPlayerSpeaker(speakerName) {
    if (!speakerName) return false;
    /* 检查 SillyTavern 的 name1 */
    try {
      var ctx = SillyTavern.getContext();
      if (ctx && ctx.name1 && speakerName === ctx.name1) return true;
    } catch (e) { }
    /* 检查 MVU 的 user.姓名 */
    try {
      var userName = _v('user.姓名', '');
      if (userName && speakerName === userName) return true;
    } catch (e) { }
    /* 检查常见代称 */
    if (speakerName === '我' || speakerName === '你' || speakerName === '玩家') return true;
    return false;
  }

  function _pickActorAvatar(name, cb) {
    const inp = document.createElement('input');
    inp.type = 'file'; inp.accept = 'image/*';
    inp.onchange = function () {
      const f = this.files[0]; if (!f) return;
      const rd = new FileReader();
      rd.onload = function (e) {
        const img2 = new Image();
        img2.onload = function () {
          let w = img2.width, h = img2.height;
          const mx = 150;
          if (w > mx || h > mx) { const r2 = Math.min(mx / w, mx / h); w = Math.round(w * r2); h = Math.round(h * r2); }
          const cv = document.createElement('canvas'); cv.width = w; cv.height = h;
          cv.getContext('2d').drawImage(img2, 0, 0, w, h);
          const out = cv.toDataURL('image/jpeg', 0.7);
          _setActorAvatar(name, out);
          if (cb) cb(out);
        };
        img2.src = e.target.result;
      };
      rd.readAsDataURL(f);
    };
    inp.click();
  }

