  const THEME_KEYS = Object.keys(THEMES);
  const STORAGE_KEY = 'av-theme';
  const FONT_STORAGE_KEY = 'av-font-settings';
  function _loadFontSettings() {
    try { const raw = localStorage.getItem(FONT_STORAGE_KEY); if (raw) return JSON.parse(raw); } catch (e) { }
    return { family: 'system', customScale: 1.0 };
  }
  function _saveFontSettings(settings) { try { localStorage.setItem(FONT_STORAGE_KEY, JSON.stringify(settings)); } catch (e) { } }
  const FONT_FAMILIES = {
    system: { name: '系统默认', value: "-apple-system,'Segoe UI','Microsoft YaHei',sans-serif" },
    serif: { name: '宋体/衬线', value: "'Noto Serif SC','SimSun',serif" },
    rounded: { name: '圆体', value: "'Noto Sans SC','PingFang SC',sans-serif" },
    elegant: { name: '楷体', value: "'LXGW WenKai','KaiTi',cursive" },
    custom: { name: '自定义字体', value: "'AVCustomFont',sans-serif" }
  };
  /* ═══ 自定义字体文件管理（IndexedDB，突破 localStorage 5MB 限制） ═══ */
  const FONT_DB_NAME = 'av-font-db';
  const FONT_DB_VERSION = 1;
  const FONT_STORE = 'fonts';
  const FONT_KEY_DATA = 'custom-font-data';
  const FONT_KEY_NAME = 'custom-font-name';

  /* 内存缓存，避免每次渲染都异步读 DB */
  var _fontDataCache = null;
  var _fontNameCache = '';
  var _fontLoaded = false;

  function _openFontDB() {
    return new Promise(function(resolve, reject) {
      try {
        var req = indexedDB.open(FONT_DB_NAME, FONT_DB_VERSION);
        req.onupgradeneeded = function(e) {
          var db = e.target.result;
          if (!db.objectStoreNames.contains(FONT_STORE)) {
            db.createObjectStore(FONT_STORE);
          }
        };
        req.onsuccess = function(e) { resolve(e.target.result); };
        req.onerror = function(e) { reject(e.target.error); };
      } catch(err) { reject(err); }
    });
  }

  function _fontDBPut(key, value) {
    return _openFontDB().then(function(db) {
      return new Promise(function(resolve, reject) {
        var tx = db.transaction(FONT_STORE, 'readwrite');
        tx.objectStore(FONT_STORE).put(value, key);
        tx.oncomplete = function() { resolve(true); };
        tx.onerror = function() { reject(tx.error); };
      });
    });
  }

  function _fontDBGet(key) {
    return _openFontDB().then(function(db) {
      return new Promise(function(resolve) {
        var tx = db.transaction(FONT_STORE, 'readonly');
        var req = tx.objectStore(FONT_STORE).get(key);
        req.onsuccess = function() { resolve(req.result || ''); };
        req.onerror = function() { resolve(''); };
      });
    });
  }

  function _fontDBDeleteAll() {
    return _openFontDB().then(function(db) {
      return new Promise(function(resolve) {
        var tx = db.transaction(FONT_STORE, 'readwrite');
        tx.objectStore(FONT_STORE).delete(FONT_KEY_DATA);
        tx.objectStore(FONT_STORE).delete(FONT_KEY_NAME);
        tx.oncomplete = function() { resolve(true); };
        tx.onerror = function() { resolve(false); };
      });
    });
  }

  /* 启动时预加载字体到内存缓存 */
  function _preloadFontFromDB() {
    return Promise.all([_fontDBGet(FONT_KEY_DATA), _fontDBGet(FONT_KEY_NAME)])
      .then(function(arr) {
        _fontDataCache = arr[0] || '';
        _fontNameCache = arr[1] || '';
        _fontLoaded = true;
        return { data: _fontDataCache, name: _fontNameCache };
      })
      .catch(function() {
        _fontDataCache = '';
        _fontNameCache = '';
        _fontLoaded = true;
        return { data: '', name: '' };
      });
  }

  function _getCustomFont() {
    /* 同步返回内存缓存；首次未加载时返回空，同时触发异步预加载 */
    if (!_fontLoaded) {
      _preloadFontFromDB().then(function() { _ensureCss(); _render(); });
      return '';
    }
    return _fontDataCache || '';
  }

  function _getCustomFontName() {
    if (!_fontLoaded) return '';
    return _fontNameCache || '';
  }

  function _clearCustomFont() {
    _fontDataCache = '';
    _fontNameCache = '';
    _fontLoaded = true;
    _fontDBDeleteAll();
  }

  function _pickCustomFont(cb) {
    var inp = document.createElement('input');
    inp.type = 'file'; inp.accept = '.ttf,.otf,.woff,.woff2';
    inp.onchange = function() {
      var f = this.files[0]; if (!f) return;
      if (f.size > 30 * 1024 * 1024) {
        if (typeof triggerSlash === 'function') triggerSlash('/echo severity=error 字体文件过大（限制30MB以内）');
        return;
      }
      var rd = new FileReader();
      rd.onload = function(e) {
        var dataUrl = e.target.result;
        _fontDBPut(FONT_KEY_DATA, dataUrl)
          .then(function() { return _fontDBPut(FONT_KEY_NAME, f.name); })
          .then(function() {
            _fontDataCache = dataUrl;
            _fontNameCache = f.name;
            _fontLoaded = true;
            if (cb) cb(f.name);
          })
          .catch(function(ex) {
            console.warn('[Font] IndexedDB 存储失败:', ex);
            if (typeof triggerSlash === 'function') triggerSlash('/echo severity=error 字体存储失败：' + (ex && ex.message ? ex.message : '未知错误'));
          });
      };
      rd.readAsDataURL(f);
    };
    inp.click();
  }
  function _getFontFamily() { const s = _loadFontSettings(); if (s.family === 'custom' && _getCustomFont()) return "'AVCustomFont',sans-serif"; return FONT_FAMILIES[s.family] ? FONT_FAMILIES[s.family].value : FONT_FAMILIES.system.value; }
  function _getFontScale() { const s = _loadFontSettings(); return s.customScale !== undefined ? s.customScale : 1.0; }

  let _currentTheme = localStorage.getItem(STORAGE_KEY) || 'pearl';
  if (!THEMES[_currentTheme]) _currentTheme = 'pearl';
  function _t() { return THEMES[_currentTheme]; }

