  var _defaultTagGrad = function(color) { var r = parseInt(color.slice(1,3),16); var g = parseInt(color.slice(3,5),16); var b = parseInt(color.slice(5,7),16); return 'linear-gradient(135deg,rgb('+Math.floor(r*.15)+','+Math.floor(g*.15)+','+Math.floor(b*.15)+'),rgb('+Math.floor(r*.3)+','+Math.floor(g*.3)+','+Math.floor(b*.3)+'))'; };
