  function _getAvailActors(userLevel) {
    var maxIdx = LEVEL_ORDER.indexOf(userLevel); if (maxIdx < 0) maxIdx = 0;
    var arr = [];
    for (var co in COMPANIES) { var acts = COMPANIES[co].actors; for (var i = 0; i < acts.length; i++) { var an = acts[i]; if (!_canPairWith(an)) continue; var ad = _v('艺人.' + co + '.' + an, {}); var lv = ad['\u7b49\u7ea7'] || 'F级'; var li = LEVEL_ORDER.indexOf(lv); if (li <= maxIdx + 1) arr.push({name:an,level:lv,company:co,gender:ACTOR_GENDERS[an]||'男',pairTypes:_getPairTypes(an)}); } }
    arr.sort(function(a,b){return LEVEL_ORDER.indexOf(a.level)-LEVEL_ORDER.indexOf(b.level);}); return arr;
  }
  var LEVEL_ORDER = ['F级', 'D级', 'C级', 'B级', 'A级'];

  function _getScriptCover(tags, idx) {
    var covers = USER_CONFIG.scriptCovers || {};
    if (typeof covers !== 'object' || Array.isArray(covers)) return '';
    for (var i = 0; i < tags.length; i++) {
      var arr = covers[tags[i]];
      if (arr && arr.length) return arr[idx % arr.length];
    }
    var def = covers['_default'];
    if (def && def.length) return def[idx % def.length];
    return '';
  }

