  /* ═══ 季节判断（基于周数） ═══ */
  function _getSeason(weekNum) {
    /* 1-12周春 13-24周夏 25-36周秋 37-48周冬 循环 */
    var w = ((weekNum - 1) % 48) + 1;
    if (w <= 12) return { name: '春', icon: '🌸', color: '#f0a0c8' };
    if (w <= 24) return { name: '夏', icon: '☀️', color: '#f0c040' };
    if (w <= 36) return { name: '秋', icon: '🍂', color: '#d08040' };
    return { name: '冬', icon: '❄️', color: '#80c0e0' };
  }

