  /* 右侧图片自定义（本地导入） */
  const HOME_RIGHT_KEY = 'av-img-home-right';
  function _getHomeRight() { try { return localStorage.getItem(HOME_RIGHT_KEY) || USER_CONFIG.homeRight || ''; } catch (e) { return USER_CONFIG.homeRight || ''; } }
  function _clearHomeRight() { try { localStorage.removeItem(HOME_RIGHT_KEY); } catch (e) { } }
  function _pickHomeRight(cb) {
    const inp = document.createElement('input');
    inp.type = 'file'; inp.accept = 'image/*';
    inp.onchange = function () {
      const f = this.files[0]; if (!f) return;
      const rd = new FileReader();
      rd.onload = function (e) {
        const img4 = new Image();
        img4.onload = function () {
          let w = img4.width, h = img4.height;
          const mx = 400;
          if (w > mx || h > mx) { const r4 = Math.min(mx / w, mx / h); w = Math.round(w * r4); h = Math.round(h * r4); }
          const cv = document.createElement('canvas'); cv.width = w; cv.height = h;
          cv.getContext('2d').drawImage(img4, 0, 0, w, h);
          const out = cv.toDataURL('image/jpeg', 0.75);
          try { localStorage.setItem(HOME_RIGHT_KEY, out); } catch (x) { }
          if (cb) cb(out);
        };
        img4.src = e.target.result;
      };
      rd.readAsDataURL(f);
    };
    inp.click();
  }

