/* LRC歌词解析（修复正则lastIndex bug） */
function _parseLRC(lrcText) {
  if (!lrcText) return [];
  const lines = lrcText.split(/\r?\n/);
  const result = [];
  for (const line of lines) {
    const timeMatches = line.match(/\[(\d{1,2}):(\d{2})(?:\.(\d{1,3}))?\]/g);
    const text = line.replace(/\[(\d{1,2}):(\d{2})(?:\.(\d{1,3}))?\]/g, '').trim();
    if (timeMatches && text) {
      for (const tm of timeMatches) {
        const m = tm.match(/\[(\d{1,2}):(\d{2})(?:\.(\d{1,3}))?\]/);
        if (!m) continue;
        const time = 60 * Number(m[1]) + Number(m[2]) + (m[3] ? Number(m[3].padEnd(3, '0')) : 0) / 1000;
        result.push({ time: Math.max(0, time - 0.5), text });
      }
    }
  }
  result.sort((a, b) => a.time - b.time);
  return result;
}

/* ═══════════════════════════════════════
   歌词自动翻译 + 缓存
   ═══════════════════════════════════════ */
const LYRIC_TRANS_CACHE_KEY = 'av-lyric-trans-cache';
const LYRIC_TRANS_CACHE_MAX = 200;

function _loadLyricTransCache() {
  try { const r = localStorage.getItem(LYRIC_TRANS_CACHE_KEY); if (r) return JSON.parse(r); } catch (e) { }
  return {};
}
function _saveLyricTransCache(cache) {
  const keys = Object.keys(cache);
  if (keys.length > LYRIC_TRANS_CACHE_MAX) {
    keys.sort((a, b) => (cache[a].ts || 0) - (cache[b].ts || 0));
    for (let i = 0; i < keys.length - LYRIC_TRANS_CACHE_MAX; i++) delete cache[keys[i]];
  }
  try { localStorage.setItem(LYRIC_TRANS_CACHE_KEY, JSON.stringify(cache)); } catch (e) { }
}

/* 判断是不是外语歌词：只要不是纯中文，就认为需要翻译 */
function _needTranslate(text) {
  if (!text) return false;
  const hasChinese = /[\u4e00-\u9fa5]/.test(text);
  const hasForeign = /[a-zA-Z\u3040-\u30ff\uac00-\ud7af]/.test(text);
  return !hasChinese && hasForeign;
}

/* 整段翻译：把多行文本一次性发给辅助API */
async function _translateLyricsBatch(lines) {
  if (!lines || !lines.length) return null;
  const api = _getAuxApi();
  if (!api || !api.endpoint || !api.key) {
    console.warn('[歌词翻译] 没有配置辅助API');
    return null;
  }

  const joined = lines.map((l, i) => (i + 1) + '. ' + l).join('\n');
  const prompt = '请把下面这段歌词逐行翻译成中文。要求：\n' +
    '1. 保持行数完全一致，不要合并、不要省略、不要跳过任何一行\n' +
    '2. 每行输出格式为：行号. 中文翻译\n' +
    '3. 如果某行是纯语气词、人名、或无需翻译的内容，也请原样保留\n' +
    '4. 不要输出任何额外解释\n\n' +
    '歌词：\n' + joined;

  const msgs = [
    { role: 'system', content: '你是一个歌词翻译助手。逐行翻译，不合并、不省略、不跳过，严格保持行数一致。' },
    { role: 'user', content: prompt }
  ];

  try {
    console.log('[歌词翻译] 开始翻译 ' + lines.length + ' 行');
    const reply = await _callApi(msgs, { temperature: 0.3, max_tokens: 2000 });
    if (!reply) { console.warn('[歌词翻译] API返回空'); return null; }

    const outLines = reply.split('\n')
      .map(s => s.replace(/^\s*\d+[\.\、\)]\s*/, '').trim())
      .filter(s => s.length > 0);

    console.log('[歌词翻译] 返回 ' + outLines.length + ' 行');

    if (outLines.length !== lines.length) {
      console.warn('[歌词翻译] 行数不匹配，放弃。原', lines.length, '译', outLines.length);
      return null;
    }
    return outLines;
  } catch (e) {
    console.warn('[歌词翻译] 失败:', e);
    return null;
  }
}
/* 把翻译合并进歌词数组：每句变成 { time, text, trans } */
async function _attachTranslation(lyrics, songKey) {
  if (!lyrics || !lyrics.length) return lyrics;
  if (!_isLyricTransEnabled()) {
    for (let i = 0; i < lyrics.length; i++) lyrics[i].trans = '';
    return lyrics;
  }

  const cache = _loadLyricTransCache();
  if (songKey && cache[songKey] && Array.isArray(cache[songKey].trans)) {
    const trans = cache[songKey].trans;
    if (trans.length === lyrics.length) {
      for (let i = 0; i < lyrics.length; i++) lyrics[i].trans = trans[i] || '';
      return lyrics;
    }
  }

  const needIdx = [];
  const needText = [];
  for (let i = 0; i < lyrics.length; i++) {
    const t = lyrics[i].text;
    if (!t) continue;
    const hasChinese = /[\u4e00-\u9fa5]/.test(t);
    const hasForeign = /[a-zA-Z\u3040-\u30ff\uac00-\ud7af]/.test(t);
    if (!hasChinese && hasForeign) {
      needIdx.push(i);
      needText.push(t);
    }
  }

  if (!needIdx.length) {
    for (let i = 0; i < lyrics.length; i++) lyrics[i].trans = '';
    return lyrics;
  }

if (typeof triggerSlash === 'function') triggerSlash('/echo severity=info 待翻译:' + needText.length + '行, API:' + (_getAuxApi() ? _getAuxApi().name : '无'));
  const translated = await _translateLyricsBatch(needText);
if (typeof triggerSlash === 'function') triggerSlash('/echo severity=info API返回:' + (translated ? translated.length + '行' : 'null'));

  for (let i = 0; i < lyrics.length; i++) lyrics[i].trans = '';

  if (translated && translated.length === needIdx.length) {
    for (let k = 0; k < needIdx.length; k++) {
      lyrics[needIdx[k]].trans = translated[k] || '';
    }
    if (songKey) {
      const fullTrans = lyrics.map(l => l.trans || '');
      cache[songKey] = { trans: fullTrans, ts: Date.now() };
      _saveLyricTransCache(cache);
    }
  }
  return lyrics;
}

  function _getCurrentLyricIndex() {
    if (!_playerAudio || !_playerState.lyrics.length) return -1;
    const cur = _playerAudio.currentTime || 0;
    let idx = _playerState.lyrics.length - 1;
    for (let i = 0; i < _playerState.lyrics.length; i++) {
      if (cur < _playerState.lyrics[i].time) { idx = i - 1; break; }
    }
    return idx;
  }

  const RADIO_HISTORY_KEY = 'av-radio-history';
