/* ═══════════════════════════════════════
   内置多源音乐库（替代外部 Music.js）
   ═══════════════════════════════════════ */
const _MUSIC_API = {
  base: 'https://music-api.gdstudio.xyz/api.php',
  sources: ['netease', 'tencent', 'kugou', 'kuwo']
};

async function _mFetch(url, timeout = 5000) {
  const ctrl = new AbortController();
  const timer = setTimeout(() => ctrl.abort(), timeout);
  try {
    const res = await fetch(url, { method: 'GET', signal: ctrl.signal });
    clearTimeout(timer);
    if (!res.ok) return null;
    return await res.json();
  } catch (e) {
    clearTimeout(timer);
    return null;
  }
}

function _mCheckAudio(url) {
  return new Promise((resolve) => {
    const audio = new Audio();
    let timer;
    const cleanup = () => {
      audio.removeEventListener('loadedmetadata', ok);
      audio.removeEventListener('error', fail);
      clearTimeout(timer);
      audio.src = '';
    };
    const ok = () => { cleanup(); resolve(true); };
    const fail = () => { cleanup(); resolve(false); };
    audio.preload = 'metadata';
    audio.src = url;
    timer = setTimeout(fail, 3000);
    audio.addEventListener('loadedmetadata', ok);
    audio.addEventListener('error', fail);
  });
}

async function _mSearchOne(keyword, source) {
  const b = _MUSIC_API.base;
  const list = await _mFetch(`${b}?types=search&source=${source}&name=${encodeURIComponent(keyword)}&count=15&pages=1`);
  if (!list || !Array.isArray(list) || !list.length) return null;

  for (const item of list) {
    try {
      const id = item.id;
      const urlRes = await _mFetch(`${b}?types=url&source=${source}&id=${id}&br=999`);
      if (!urlRes || !urlRes.url) continue;
      if (!(await _mCheckAudio(urlRes.url))) continue;

      const [lyricRes, picRes] = await Promise.all([
        _mFetch(`${b}?types=lyric&source=${source}&id=${id}`).catch(() => null),
        item.pic_id ? _mFetch(`${b}?types=pic&source=${source}&id=${item.pic_id}`).catch(() => null) : null
      ]);

      return {
        Url: urlRes.url,
        Lyric: lyricRes && lyricRes.lyric ? lyricRes.lyric : '',
        Cover: picRes && picRes.url ? picRes.url : '',
        Name: item.name || keyword,
        Singer: item.artist ? item.artist.join(',') : '',
        Source: source
      };
    } catch (e) {
      continue;
    }
  }
  return null;
}

async function _ensureMusicLib() {
  if (globalThis.Music && globalThis.Music.SearchMusic) { _radioMusicLoaded = true; return true; }
  globalThis.Music = {
    SearchMusic: async function (keyword, artist) {
      if (!keyword) return null;
      const kw = artist ? `${keyword} - ${artist}` : keyword;
      for (const source of _MUSIC_API.sources) {
        const result = await _mSearchOne(kw, source);
        if (result) {
          console.log('[Music] 命中音源:', source, '/', result.Name);
          return result;
        }
      }
      console.warn('[Music] 所有音源均未找到:', kw);
      return null;
    }
  };
  _radioMusicLoaded = true;
  return true;
}

  /* 搜索缓存 */
  const MUSIC_CACHE_KEY = 'av-music-cache';
  function _loadMusicCache() { try { const r = localStorage.getItem(MUSIC_CACHE_KEY); if (r) return JSON.parse(r); } catch (e) { } return {}; }
  function _saveMusicCache(cache) { try { localStorage.setItem(MUSIC_CACHE_KEY, JSON.stringify(cache)); } catch (e) { } }
  function _cacheMusicResult(keyword, result) {
    const cache = _loadMusicCache();
    cache[keyword] = { data: result, ts: Date.now() };
    const keys = Object.keys(cache);
    if (keys.length > 80) { keys.sort((a, b) => cache[a].ts - cache[b].ts); for (let i = 0; i < keys.length - 80; i++) delete cache[keys[i]]; }
    _saveMusicCache(cache);
  }
  function _getCachedMusic(keyword) {
    const cache = _loadMusicCache();
    const entry = cache[keyword];
    if (!entry) return null;
    if (Date.now() - entry.ts > 3600000) return null;
    return entry.data;
  }

  /* 批量搜索歌手歌单（优先用辅助API获取真实歌名列表） */
  async function _searchArtistSongs(artistName, count) {
    if (!artistName) return [];
    const libOk = await _ensureMusicLib();
    if (!libOk || !globalThis.Music) return [];

    /* 步骤1：尝试用辅助API获取真实歌曲名称列表 */
    let songNames = [];
    const auxApi = _getAuxApi();
    if (auxApi && auxApi.endpoint && auxApi.key) {
      try {
        const msgs = [
          { role: 'system', content: '请列出歌手"' + artistName + '"最知名的8-12首歌曲名称。只输出歌曲名称，每行一首，不要编号，不要其他文字。只输出真实存在的歌曲。' },
          { role: 'user', content: '列出' + artistName + '的歌曲' }
        ];
        const reply = await _callApi(msgs, { temperature: 0.3, max_tokens: 300 });
        songNames = reply.split('\n').map(function (s) { return s.replace(/^\d+[\.\、\)\s]+/, '').trim(); }).filter(function (s) { return s.length > 0 && s.length < 30; });
      } catch (e) { console.warn('[AV Radio] AI song list fail:', e); }
    }

    /* 步骤2：如果API没返回结果，回退到关键词搜索 */
    if (!songNames.length) {
      songNames = [artistName, artistName + ' 歌曲', artistName + ' 热门', artistName + ' 经典', artistName + ' 新歌'];
    }

    /* 步骤3：逐首用歌名+歌手名搜索 */
    const found = [];
    const seen = new Set();
    for (const songName of songNames) {
      const kw = songName + ' ' + artistName;
      try {
        const cached = _getCachedMusic(kw);
        let result = null;
        if (cached && cached.Name) { result = cached; }
        else {
          result = await globalThis.Music.SearchMusic(kw);
          if (result && result.Name) _cacheMusicResult(kw, result);
        }
        if (result && result.Name && !seen.has(result.Name)) {
          seen.add(result.Name);
          found.push({ name: result.Name, artist: result.Singer || artistName, keyword: (result.Name || '') + ' ' + (result.Singer || artistName), url: result.Url || '', lyric: result.Lyric || '' });
          _cacheMusicResult((result.Name || '') + ' ' + (result.Singer || artistName), result);
        }
      } catch (e) { console.warn('[AV Radio] Song search fail:', kw, e); }
      if (found.length >= (count || 10)) break;
    }
    return found;
  }

  function _loadRadioHistory() { try { return JSON.parse(localStorage.getItem(RADIO_HISTORY_KEY) || '[]'); } catch (e) { return []; } }
  function _saveRadioHistory(arr) { try { localStorage.setItem(RADIO_HISTORY_KEY, JSON.stringify(arr.slice(0, 30))); } catch (e) { } }
  function _addRadioHistory(name, artist) { if (!name) return; const h = _loadRadioHistory().filter(s => s.name !== name); h.unshift({ name, artist }); _saveRadioHistory(h); }

  function _loadRadioFavorites() { try { return JSON.parse(localStorage.getItem(RADIO_FAV_KEY) || '[]'); } catch (e) { return []; } }
  function _saveRadioFavorites(arr) { try { localStorage.setItem(RADIO_FAV_KEY, JSON.stringify(arr)); } catch (e) { } }
  function _isRadioFavorite(name) { return _loadRadioFavorites().some(s => s.name === name); }
  function _toggleRadioFavorite(name, artist) {
    if (!name) return;
    let fav = _loadRadioFavorites();
    const idx = fav.findIndex(s => s.name === name);
    if (idx >= 0) fav.splice(idx, 1); else fav.unshift({ name, artist });
    _saveRadioFavorites(fav);
  }

async function _playerPlaySong(name, artist) {
  if (!name) return;
  const libOk = await _ensureMusicLib();
  if (!libOk || !globalThis.Music) { if (typeof triggerSlash === 'function') triggerSlash('/echo severity=error 音乐库加载失败'); return; }
  try {
    const result = await globalThis.Music.SearchMusic(name + (artist ? ' ' + artist : ''));
    if (!result || !result.Url) { if (typeof triggerSlash === 'function') triggerSlash('/echo severity=warning 未找到歌曲'); return; }
    if (_playerAudio) { _playerAudio.pause(); _playerAudio.src = ''; }
    _playerAudio = new Audio(result.Url);
    /* 获取歌词 */
    let lyrics = [];
    let lyricText = '';
    try {
      if (result.Lyric) { lyricText = result.Lyric; lyrics = _parseLRC(result.Lyric); }
      else if (globalThis.Music && globalThis.Music.GetLyric) {
        const lyricResult = await globalThis.Music.GetLyric(result.Id || result.id);
        if (lyricResult) { lyricText = lyricResult; lyrics = _parseLRC(lyricResult); }
      }
      /* 自动翻译：用歌名+歌手当缓存key */
      if (lyrics.length) {
        const songKey = (result.Name || name || '') + ' - ' + (result.Singer || artist || '');
        lyrics = await _attachTranslation(lyrics, songKey);
      }
    } catch (e) { console.warn('[AV Player] 歌词获取失败:', e); }
    _playerState = { name: result.Name || name, artist: result.Singer || artist || '', coverUrl: result.Cover || '', playing: true, lyrics, lyricText };
    _playerAudio.play().catch(() => {});
    _playerAudio.onended = () => {
      /* 自动播放下一首 */
      if (_playerState.playlist.length > 0) {
        _playerNext();
      } else {
        _playerState.playing = false;
        _render();
      }
    };
    _addRadioHistory(_playerState.name, _playerState.artist);
    _render();
  } catch (e) { if (typeof triggerSlash === 'function') triggerSlash('/echo severity=error 播放失败：' + (e.message || '')); }
}

  function _playerToggle() {
    if (!_playerAudio || !_playerState.name) return;
    if (_playerState.playing) { _playerAudio.pause(); _playerState.playing = false; }
    else { _playerAudio.play().catch(() => {}); _playerState.playing = true; }
    _render();
  }

  function _playerPrev() {
    const pl = _playerState.playlist;
    if (pl.length > 0) {
      let idx = _playerState.playIndex;
      if (_playerState.playMode === 'shuffle') {
        idx = Math.floor(Math.random() * pl.length);
      } else {
        idx = idx > 0 ? idx - 1 : pl.length - 1;
      }
      _playerState.playIndex = idx;
      _playerPlaySong(pl[idx].name, pl[idx].artist);
    } else {
      const h = _loadRadioHistory();
      const curIdx = h.findIndex(s => s.name === _playerState.name);
      const prev = curIdx > 0 ? h[curIdx - 1] : h[h.length - 1];
      if (prev) _playerPlaySong(prev.name, prev.artist);
    }
  }
  function _playerNext() {
    const pl = _playerState.playlist;
    if (pl.length > 0) {
      let idx = _playerState.playIndex;
      if (_playerState.playMode === 'shuffle') {
        idx = Math.floor(Math.random() * pl.length);
      } else {
        idx = (idx < pl.length - 1) ? idx + 1 : 0;
      }
      _playerState.playIndex = idx;
      _playerPlaySong(pl[idx].name, pl[idx].artist);
    } else {
      const h = _loadRadioHistory();
      const curIdx = h.findIndex(s => s.name === _playerState.name);
      const next = (curIdx >= 0 && curIdx < h.length - 1) ? h[curIdx + 1] : h[0];
      if (next) _playerPlaySong(next.name, next.artist);
    }
  }

  function _fmtTime(s) { if (!s || isNaN(s)) return '0:00'; const m = Math.floor(s / 60); return m + ':' + String(Math.floor(s % 60)).padStart(2, '0'); }

function _startProgressUpdate() {
  if (_progressTimer) clearInterval(_progressTimer);
  _progressTimer = setInterval(() => {
    if (!_playerAudio || !_playerState.playing) return;
    const cur = _playerAudio.currentTime || 0;
    const dur = _playerAudio.duration || 0;
    const pct = dur > 0 ? (cur / dur * 100) : 0;
    const $fill = $('#av-p-fill'); if ($fill.length) $fill.css('width', pct + '%');
    const $cur = $('#av-p-cur'); if ($cur.length) $cur.text(_fmtTime(cur));
    const $dur = $('#av-p-dur'); if ($dur.length) $dur.text(_fmtTime(dur));
    /* 歌词两行同步（支持原文+翻译双行） */
    if (_playerState.lyrics.length) {
      const lyricIdx = _getCurrentLyricIndex();
      const $curL = $('#av-p-lyric-cur');
      const $nxtL = $('#av-p-lyric-nxt');
      const fmtLyric = (ly) => {
        if (!ly) return '';
        if (ly.trans && ly.trans.trim() && ly.trans.trim() !== ly.text.trim()) {
          return ly.text + '\n' + ly.trans;
        }
        return ly.text;
      };
      if ($curL.length) {
        if (lyricIdx >= 0) {
          $curL.text(fmtLyric(_playerState.lyrics[lyricIdx]));
          const nxt = _playerState.lyrics[lyricIdx + 1];
          $nxtL.text(nxt ? fmtLyric(nxt) : '');
        } else {
          $curL.text('♪');
          $nxtL.text(_playerState.lyrics[0] ? fmtLyric(_playerState.lyrics[0]) : '');
        }
      }
    }
  }, 100);
}

