      $r.html(rHtml);
      const plData = songs.map(s => ({ name: s.name, artist: s.artist }));
      $r.find('#av-ps-all-seq').on('click', () => { _playerState.playlist = plData; _playerState.playIndex = 0; _playerState.playMode = 'sequence'; _playerPlaySong(plData[0].name, plData[0].artist); w.remove(); });
      $r.find('#av-ps-all-shuf').on('click', () => { _playerState.playlist = plData; const ri = Math.floor(Math.random() * plData.length); _playerState.playIndex = ri; _playerState.playMode = 'shuffle'; _playerPlaySong(plData[ri].name, plData[ri].artist); w.remove(); });
      $r.find('.av-ps-item').on('click', function () { const idx2 = parseInt($(this).data('idx')); _playerState.playlist = plData; _playerState.playIndex = idx2; _playerPlaySong($(this).data('song'), $(this).data('artist')); w.remove(); });
      $btn.prop('disabled', false).text('搜歌手');
