    w.find('#av-ps-input').on('keydown', e => { if (e.key === 'Enter') w.find('#av-ps-btn-song').click(); });
    w.find('.av-ps-quick').on('click', function () { _playerPlaySong($(this).data('song'), $(this).data('artist')); w.remove(); });
