  /* ═══ 图片回复处理（发图片后 AI 回应） ═══ */
  async function _handleSmsImageReply($c, label, contextText) {
    if (!_commContact) return;
    _showSmsTyping(_commContact);
    var reply = await _smsCallApi(_commContact, contextText, 'sms');
    _hideSmsTyping(_commContact);
    if (reply) {
      var data = _loadSmsData();
      var msgs = _parseMsgBlocks(reply);
      var baseTs = Date.now();
      for (var i = 0; i < msgs.length; i++) {
        data[_commContact].push({ from: _commContact, text: msgs[i], ts: baseTs + i * 800 });
        _incSmsUnread(_commContact);
      }
      _saveSmsData(data);
    }
    _drawComm($c);
  }

