  /* ═══ AI 领取红包/转账 ═══ */
  async function _aiReceiveHongbao($c, contact, amount, remark, type) {
    /* 先标记为已领取 */
    var data = _loadSmsData();
    var msgs = data[contact] || [];
    for (var i = msgs.length - 1; i >= 0; i--) {
      if (msgs[i].type === type && !msgs[i].opened) {
        msgs[i].opened = true;
        break;
      }
    }
    _saveSmsData(data);

    /* AI 回应 */
    _showSmsTyping(contact);
    var contextText = type === 'hongbao'
      ? '[玩家发了一个红包，金额' + amount + '金币，备注"' + remark + '"]'
      : '[玩家转账' + amount + '金币给你]';

    var reply = await _smsCallApi(contact, contextText, 'sms');
    _hideSmsTyping(contact);

    if (reply) {
      data = _loadSmsData();
      var _msgs = _parseMsgBlocks(reply);
      var baseTs = Date.now();
      for (var j = 0; j < _msgs.length; j++) {
        var _raw = _msgs[j];
        var _delay = j * 600;
        var handled = _processSmsInstruction(_raw, contact, data, baseTs + _delay, $c);
        if (handled) continue;
        data[contact].push({ from: contact, text: _raw, ts: baseTs + _delay });
        _incSmsUnread(contact);
      }
      _saveSmsData(data);
    }
    _drawComm($c);

    /* ═══ 最后统一触发金币变动 ═══ */
    setTimeout(function() { _flushCoinChanges(); }, 1000);
  }

/* ═══ 群聊存储 ═══ */
var GROUP_STORAGE_KEY = 'av-group-chats';
/* 结构：{ '群id': { id, name, members: ['A','B'], creator: '我', createdAt, messages: [], avatarCache: '' } } */
function _loadGroups() {
  try { var r = localStorage.getItem(GROUP_STORAGE_KEY); if (r) return JSON.parse(r); } catch(e) {}
  return {};
}
function _saveGroups(d) {
  try { localStorage.setItem(GROUP_STORAGE_KEY, JSON.stringify(d)); } catch(e) {}
}
function _getGroup(groupId) {
  var gs = _loadGroups();
  return gs[groupId] || null;
}
function _setGroup(groupId, groupData) {
  var gs = _loadGroups();
  gs[groupId] = groupData;
  _saveGroups(gs);
}
function _deleteGroup(groupId) {
  var gs = _loadGroups();
  delete gs[groupId];
  _saveGroups(gs);
}
/* ═══ 群聊未读 ═══ */
var GROUP_UNREAD_KEY = 'av-group-unread';
function _loadGroupUnread() { try { var r = localStorage.getItem(GROUP_UNREAD_KEY); if (r) return JSON.parse(r); } catch(e) {} return {}; }
