/* 用 canvas 画九宫格群头像 */
function _generateGroupAvatar(members, cb) {
  var size = 120;
  var canvas = document.createElement('canvas');
  canvas.width = size;
  canvas.height = size;
  var ctx = canvas.getContext('2d');
  ctx.fillStyle = '#e0e0e0';
  ctx.fillRect(0, 0, size, size);

  var n = Math.min(members.length, 9);
  var gridSize = n <= 1 ? 1 : (n <= 4 ? 2 : 3);
  var cellSize = size / gridSize;

  var loaded = 0;
  var total = n;
  var images = [];

  function tryFinish() {
    loaded++;
    if (loaded < total) return;
    for (var i = 0; i < images.length; i++) {
      var img = images[i];
      var row = Math.floor(i / gridSize);
      var col = i % gridSize;
      ctx.save();
      ctx.beginPath();
      ctx.rect(col * cellSize, row * cellSize, cellSize, cellSize);
      ctx.clip();
      if (img) {
        var scale = Math.max(cellSize / img.width, cellSize / img.height);
        var w = img.width * scale;
        var h = img.height * scale;
        var dx = col * cellSize + (cellSize - w) / 2;
        var dy = row * cellSize + (cellSize - h) / 2;
        ctx.drawImage(img, dx, dy, w, h);
      } else {
        ctx.fillStyle = '#cccccc';
        ctx.fillRect(col * cellSize, row * cellSize, cellSize, cellSize);
        ctx.fillStyle = '#666666';
        ctx.font = 'bold ' + Math.floor(cellSize * 0.5) + 'px sans-serif';
        ctx.textAlign = 'center';
        ctx.textBaseline = 'middle';
        ctx.fillText('?', col * cellSize + cellSize / 2, row * cellSize + cellSize / 2);
      }
      ctx.restore();
      ctx.strokeStyle = '#ffffff';
      ctx.lineWidth = 1;
      ctx.strokeRect(col * cellSize, row * cellSize, cellSize, cellSize);
    }
    var dataUrl = canvas.toDataURL('image/jpeg', 0.75);
    if (cb) cb(dataUrl);
  }

  if (!total) { tryFinish(); return; }
  for (var i = 0; i < n; i++) {
    (function(idx) {
      var name = members[idx];
      var bg = _getAvatar(name);
      var urlMatch = bg.match(/url\(['"]?(.+?)['"]?\)/);
      var url = urlMatch ? urlMatch[1] : '';
      if (!url) { images[idx] = null; tryFinish(); return; }
      var img = new Image();
      img.crossOrigin = 'anonymous';
      img.onload = function() { images[idx] = img; tryFinish(); };
      img.onerror = function() { images[idx] = null; tryFinish(); };
      img.src = url;
    })(i);
  }
}

