  /* 把所有联系人「上次发过之后新增的」短信，拼成一条 /send 发出去 */
  function _flushNewSms() {
    var data = _loadSmsData();
    var sent = _loadSmsSent();
    var newBlocks = [];
    var totalNew = 0;

    /* ═══ 短信 ═══ */
    for (var name in data) {
      if (!data.hasOwnProperty(name)) continue;
      var msgs = data[name] || [];
      /* ═══ 改用时间戳：sent[name] 存"上次发送的最后一条消息时间戳" ═══ */
      var lastTs = sent[name] || 0;
      var fresh = [];
      var maxTs = lastTs;
      for (var i = 0; i < msgs.length; i++) {
        var m = msgs[i];
        var mTs = m.ts || 0;
        /* 兼容旧消息（没 ts）：只在首次全发 */
        if (mTs === 0 && lastTs === 0) {
          fresh.push(m);
        } else if (mTs > lastTs) {
          fresh.push(m);
          if (mTs > maxTs) maxTs = mTs;
        }
      }
      if (!fresh.length) continue;

      var block = '【与' + name + '的短信】\n';
      for (var j = 0; j < fresh.length; j++) {
        var m2 = fresh[j];
        var who = m2.from === 'user' ? '我' : name;
        var txt;
        if (m2.type === 'sticker') txt = '[表情包]';
        else if (m2.type === 'voice') txt = '[语音] ' + (m2.voiceText || '');
        else if (m2.type === 'image') txt = '[图片]';
        else if (m2.type === 'location') txt = '[位置] ' + (m2.locationName || '');
        else if (m2.type === 'hongbao') txt = '[' + (m2.opened ? '已领取的' : '') + '红包 ￥' + (m2.amount || 0) + ']' + (m2.hbRemark ? ' ' + m2.hbRemark : '');
        else if (m2.type === 'transfer') txt = '[' + (m2.opened ? '已收款的' : '') + '转账 ￥' + (m2.amount || 0) + ']';
        else if (m2.recalled) txt = '（已撤回）';
        else txt = m2.text;
        var quoteTxt = '';
        if (m2.quoteFrom) quoteTxt = '（引用 @' + m2.quoteFrom.author + '：' + m2.quoteFrom.content.substring(0, 15) + '）';
        block += who + '：' + quoteTxt + txt + '\n';
      }
      newBlocks.push(block);
      totalNew += fresh.length;
      sent[name] = maxTs;
    }

    /* ═══ 粉丝私信 ═══ */
    var fanData = _loadFanMsgs();
    for (var fn in fanData) {
      if (!fanData.hasOwnProperty(fn)) continue;
      var fmsgs = (fanData[fn] && fanData[fn].messages) || [];
      var key = '粉丝_' + fn;
      var fLastTs = sent[key] || 0;
      var fFresh = [];
      var fMaxTs = fLastTs;
      for (var fi = 0; fi < fmsgs.length; fi++) {
        var fm = fmsgs[fi];
        var fmTs = fm.ts || 0;
        if (fmTs === 0 && fLastTs === 0) {
          fFresh.push(fm);
        } else if (fmTs > fLastTs) {
          fFresh.push(fm);
          if (fmTs > fMaxTs) fMaxTs = fmTs;
        }
      }
      if (!fFresh.length) continue;
      var fBlock = '【粉丝私信 · ' + fn + '】\n';
      for (var fj = 0; fj < fFresh.length; fj++) {
        var fm2 = fFresh[fj];
        var fwho = fm2.from === 'user' ? '我' : fn;
        var ftxt = fm2.type === 'sticker' ? '[表情包]'
                 : fm2.type === 'voice' ? '[语音] ' + (fm2.voiceText || '')
                 : fm2.text;
        fBlock += fwho + '：' + ftxt + '\n';
      }
      newBlocks.push(fBlock);
      totalNew += fFresh.length;
      sent[key] = fMaxTs;
    }

    /* ═══ 金币变动 ═══ */
    var coinChanges = _popPendingCoinChanges();
    if (coinChanges.length) {
      var totalDelta = 0;
      var coinLines = [];
      for (var ci = 0; ci < coinChanges.length; ci++) {
        var c = coinChanges[ci];
        totalDelta += c.amount;
        coinLines.push(c.desc + ' ' + (c.amount > 0 ? '+' : '') + c.amount);
      }
      var coinBlock = '【金币变动】\n' + coinLines.join('\n') + '\n总计：' + (totalDelta > 0 ? '+' : '') + totalDelta + ' 金币';
      newBlocks.push(coinBlock);
      totalNew += coinChanges.length;
    }

    /* ═══ 没有新增，什么都不发 ═══ */
    if (!newBlocks.length) return;

    _saveSmsSent(sent);

    /* ═══ 拼成一条消息发出去 ═══ */
    var summary = '【手机记录】（真实发生过，请在正文中自然引用，并更新相关变量）\n\n' + newBlocks.join('\n');
    if (typeof triggerSlash === 'function') triggerSlash('/send ' + summary + ' | /trigger');
  }
  
  /* 生成短信摘要：每个联系人取最近 3 条，最多 5 个联系人 */
  function _buildSmsSummary() {
    var data = _loadSmsData();
    var names = Object.keys(data);
    if (!names.length) return '';
    /* 按最后一条消息的时间排序（用 index 近似，越靠后越新） */
    var lines = [];
    var count = 0;
    for (var i = 0; i < names.length && count < 5; i++) {
      var name = names[i];
      var msgs = data[name] || [];
      if (!msgs.length) continue;
      var recent = msgs.slice(-3);
      var seg = '【与' + name + '的短信】\n';
      for (var j = 0; j < recent.length; j++) {
        var m = recent[j];
        var who = m.from === 'user' ? '我' : name;
        var txt = m.type === 'sticker' ? '[表情包]'
                : m.type === 'voice' ? '[语音] ' + (m.voiceText || '')
                : m.text;
        seg += who + '：' + txt + '\n';
      }
      lines.push(seg);
      count++;
    }
    if (!lines.length) return '';
    return '【最近短信记录（真实发生过，可在正文中自然引用）】\n' + lines.join('\n');
  }

