/* ═══ 消息时间戳格式化 ═══ */
function _fmtSmsTime(ts) {
  if (!ts) return '';
  var d = new Date(ts);
  var now = new Date();
  var hh = String(d.getHours()).padStart(2, '0');
  var mm = String(d.getMinutes()).padStart(2, '0');
  /* 今天 */
  if (d.toDateString() === now.toDateString()) return hh + ':' + mm;
  /* 昨天 */
  var yd = new Date(now.getTime() - 86400000);
  if (d.toDateString() === yd.toDateString()) return '昨天 ' + hh + ':' + mm;
  /* 7天内 */
  var diff = Math.floor((now - d) / 86400000);
  if (diff < 7) {
    var wd = ['日','一','二','三','四','五','六'][d.getDay()];
    return '周' + wd + ' ' + hh + ':' + mm;
  }
  /* 更早 */
  return (d.getMonth() + 1) + '月' + d.getDate() + '日 ' + hh + ':' + mm;
}

/* 判断两条消息之间是否需要显示时间戳（间隔 > 5 分钟） */
function _needSmsTime(prevTs, curTs) {
  if (!prevTs || !curTs) return true;
  return (curTs - prevTs) > 5 * 60 * 1000;
}

