    var SAVE_STORAGE_KEY = 'av-save-data';
    var SAVE_MAX_SLOTS = 6;

    function _loadSaves() { try { var r = localStorage.getItem(SAVE_STORAGE_KEY); if (r) return JSON.parse(r); } catch(e) {} return {}; }
    function _saveSaves(d) { try { localStorage.setItem(SAVE_STORAGE_KEY, JSON.stringify(d)); } catch(e) {} }

    function _drawSaveApp($c) {
      var t = _t();
      var saves = _loadSaves();
      var o = '';

      o += '<div style="text-align:center;padding:10px 0 6px;font-size:9px;color:' + t.textMuted + ';line-height:1.6">';
      o += '💡 存档会保存当前MVU变量和楼层位置<br>读档会删除存档点之后的所有楼层并恢复变量';
      o += '</div>';

      for (var i = 1; i <= SAVE_MAX_SLOTS; i++) {
        var slotKey = 'slot_' + i;
        var save = saves[slotKey];

        if (save) {
          o += '<div class="av-save-slot" style="background:' + t.surfaceHover + '">';
          o += '<div class="av-save-slot-top">';
          o += '<span class="av-save-slot-name" style="color:' + t.text + '">💾 ' + _esc(save.name || '存档' + i) + '</span>';
          o += '<span class="av-save-slot-time">' + _esc(save.timeStr || '') + '</span>';
          o += '</div>';
          o += '<div class="av-save-slot-info" style="color:' + t.textDim + '">';
          o += '第' + (save.week || '?') + '周 · ' + _esc(save.day || '') + ' · ' + _esc(save.location || '') + '<br>';
          o += '等级 ' + _esc(save.level || 'F级') + ' · 💰' + (save.coins || 0) + ' · ⭐' + (save.fame || 0);
          o += '</div>';
          o += '<div class="av-save-slot-btns">';
          o += '<button class="av-dlg-btn av-dlg-ok av-save-load" data-slot="' + slotKey + '" style="flex:1;font-size:9px;padding:8px">📂 读档</button>';
          o += '<button class="av-dlg-btn av-dlg-ok av-save-overwrite" data-slot="' + slotKey + '" style="flex:1;font-size:9px;padding:8px">💾 覆盖</button>';
          o += '<button class="av-dlg-btn av-dlg-cancel av-save-del" data-slot="' + slotKey + '" style="font-size:9px;padding:8px;color:' + t.fail + ';border-color:' + t.fail + '">🗑️</button>';
          o += '</div>';
          o += '</div>';
        } else {
          o += '<div class="av-save-slot av-save-slot-empty av-save-new" data-slot="' + slotKey + '" style="background:' + t.surfaceHover + ';color:' + t.textMuted + '">';
          o += '<div style="font-size:18px;margin-bottom:4px">＋</div>';
          o += '<div style="font-size:10px">存档位 ' + i + '</div>';
          o += '</div>';
        }
      }

      $c.html(o);

      /* 新建存档 */
      $c.find('.av-save-new').on('click', function() { _createSave($(this).data('slot'), $c); });

      /* 覆盖存档 */
      $c.find('.av-save-overwrite').on('click', function() {
        var slot = $(this).data('slot');
        showConfirmModal2('确定覆盖这个存档？', function() { _createSave(slot, $c); });
      });

      /* 读档 */
      $c.find('.av-save-load').on('click', function() {
        var slot = $(this).data('slot');
        var save = _loadSaves()[slot];
        if (!save) return;
        var t2 = _t();

        var d = '<div class="av-dlg-h">📂 读档确认</div>';
        d += '<div style="font-size:10px;color:' + t2.textDim + ';margin:8px 0;line-height:1.6">';
        d += '读取存档：' + _esc(save.name || '') + '<br><br>';
        d += '⚠️ 读档将执行以下操作：<br>';
        d += '1. 删除存档点之后的所有聊天楼层<br>';
        d += '2. 恢复存档时的MVU变量<br>';
        d += '3. 清空剧情历史缓存<br><br>';
        d += '<span style="color:' + t2.fail + ';font-weight:600">此操作！</span></div>';
        d += '<div class="av-dlg-actions"><button class="av-dlg-btn av-dlg-cancel" id="av-load-no">取消</button><button class="av-dlg-btn av-dlg-ok" id="av-load-yes" style="color:' + t2.fail + '">确认读档</button></div>';

        var w = _dialog(d);
        w.find('#av-load-no').on('click', function() { w.remove(); });
        w.find('#av-load-yes').on('click', function() {
          w.remove();
          _executeSaveLoad(save, $c);
        });
      });

      /* 删除存档 */
      $c.find('.av-save-del').on('click', function() {
        var slot = $(this).data('slot');
        showConfirmModal2('确定删除这个存档？', function() {
          var saves2 = _loadSaves();
          delete saves2[slot];
          _saveSaves(saves2);
          if (typeof triggerSlash === 'function') triggerSlash('/echo severity=success 存档已删除');
          _drawSaveApp($c);
        });
      });
    }

    function _createSave(slotKey, $c) {
      var week = _v('user.当前时间.周数', 1);
      var day = _v('user.当前时间.星期', '星期一');
      var hour = _v('user.当前时间.小时', 9);
      var location = _v('user.当前位置', '');
      var level = _v('user.等级', 'F级');
      var coins = _v('user.金币', 0);
      var fame = _v('user.名气', 0);

      /* 获取楼层ID */
      var floorId = -1;
      try {
        var context = typeof SillyTavern !== 'undefined' ? SillyTavern.getContext() : null;
        if (context && context.chat) floorId = context.chat.length - 1;
      } catch(e) {}

      /* 获取MVU变量快照 */
      var mvuSnapshot = null;
      try {
        if (typeof window.TavernHelper !== 'undefined' && window.TavernHelper.getVariables) {
          var vars = window.TavernHelper.getVariables({ type: 'message', message_id: 'latest' });
          if (vars) mvuSnapshot = JSON.parse(JSON.stringify(vars));
        }
      } catch(e) { console.warn('[Save] MVU snapshot fail:', e); }

      var saves = _loadSaves();
      saves[slotKey] = {
        name: '第' + week + '周 ' + day + ' · ' + (location || '未知'),
        timeStr: new Date().toLocaleString('zh-CN', { month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit' }),
        floorId: floorId,
        mvuSnapshot: mvuSnapshot,
        week: week,
        day: day,
        hour: hour,
        location: location,
        level: level,
        coins: coins,
        fame: fame,
        storyHistory: ScenePlayer.state.history.slice(-100)
      };
      _saveSaves(saves);

      if (typeof triggerSlash === 'function') triggerSlash('/echo severity=success 存档成功！第' + week + '周 ' + day);
      _drawSaveApp($c);
    }

    async function _executeSaveLoad(save, $c) {
      try {
        /* 1. 计算需要删除的楼层数 */
        var context = typeof SillyTavern !== 'undefined' ? SillyTavern.getContext() : null;
        if (!context || !context.chat) { if (typeof triggerSlash === 'function') triggerSlash('/echo severity=error 无法获取聊天上下文'); return; }

        var currentFloor = context.chat.length - 1;
        var targetFloor = save.floorId;
        var floorsToDelete = currentFloor - targetFloor;

        /* 2. 提示用户存档楼层位置 */
        if (typeof triggerSlash === 'function') triggerSlash('/echo severity=info 📍 存档位于第' + (targetFloor + 1) + '条消息，请手动滚动到该位置。MVU变量已恢复到存档状态。');

        /* 3. 恢复MVU变量 */
        if (save.mvuSnapshot && typeof window.TavernHelper !== 'undefined') {
          try {
            window.TavernHelper.replaceVariables(save.mvuSnapshot, { type: 'message', message_id: 'latest' });
          } catch(e) { console.warn('[Save] MVU restore fail:', e); }
        }

        /* 4. 恢复剧情历史 */
        if (save.storyHistory) {
          ScenePlayer.state.history = save.storyHistory;
          ScenePlayer._saveHistory();
        }

        /* 5. 重置ScenePlayer状态 */
        ScenePlayer.state.lastMsgId = -1;

        if (typeof triggerSlash === 'function') triggerSlash('/echo severity=success 读档成功！回到第' + (save.week || '?') + '周');
        _render();
      } catch(e) {
        console.error('[Save] Load fail:', e);
        if (typeof triggerSlash === 'function') triggerSlash('/echo severity=error 读档失败：' + (e.message || ''));
      }
    }

