    function _getLiveConfig() {
      var pop = _v('user.人气', 0);
      if (pop < 10) return { interval: [8000,15000], viewers: [1,5], giftChance: 0.02, actorChance: 0, burstCount: 1 };
      if (pop < 30) return { interval: [4000,8000], viewers: [5,30], giftChance: 0.05, actorChance: 0.01, burstCount: 1 };
      if (pop < 60) return { interval: [2000,4000], viewers: [30,200], giftChance: 0.1, actorChance: 0.03, burstCount: 2 };
      if (pop < 80) return { interval: [800,2000], viewers: [200,2000], giftChance: 0.15, actorChance: 0.05, burstCount: 3 };
      return { interval: [300,800], viewers: [2000,50000], giftChance: 0.25, actorChance: 0.08, burstCount: 5 };
    }

    function _randomDanmaku() {
      return _DANMAKU_NORMAL[Math.floor(Math.random() * _DANMAKU_NORMAL.length)];
    }

    function _randomFanName() {
      var prefixes = ['小','追光','暗恋','甜甜','星星','月亮','喵喵','深夜','可爱','快乐','阳光','幸运'];
      var suffixes = ['酱','君','sama','子','er','宝','鱼','猫','兔','鸟','星','月'];
      return prefixes[Math.floor(Math.random()*prefixes.length)] + suffixes[Math.floor(Math.random()*suffixes.length)] + Math.floor(Math.random()*999);
    }

    function _addDanmaku(text, color, isGift, name, isMe) {
      if (!_liveState) return;
      _liveState.danmaku.push({ text: text, color: color || 'rgba(255,255,255,.8)', name: name || _randomFanName(), isGift: !!isGift, isMe: !!isMe, ts: Date.now() });
      /* 保留最近200条 */
      if (_liveState.danmaku.length > 200) _liveState.danmaku = _liveState.danmaku.slice(-200);
    }

    function _tickDanmaku() {
      if (!_liveState) return;
      var cfg = _getLiveConfig();

      /* 普通弹幕：每次tick出3~burstCount*2条，从API池取 */
      var batchSize = Math.max(3, cfg.burstCount * 2);
      for (var bi = 0; bi < batchSize; bi++) {
        if (Math.random() < 0.85) {
          var msg = _getPoolDanmaku();
          _addDanmaku(msg);
        }
      }

      /* 礼物弹幕 */
      if (Math.random() < cfg.giftChance) {
        var pop = _v('user.人气', 0);
        var maxIdx = pop < 30 ? 2 : (pop < 60 ? 3 : (pop < 80 ? 4 : 5));
        var gift = _LIVE_GIFTS[Math.floor(Math.random() * (maxIdx + 1))];
        var qty = gift.value <= 10 ? Math.floor(Math.random()*5)+1 : 1;
        var giftFan = _randomFanName();
        _addDanmaku('送出了 ' + gift.icon + gift.name + ' x' + qty, '#ffb060', true, giftFan);
        _liveState.coins += gift.value * qty;
        /* 飘屏大礼物特效 */
        _liveState.danmaku.push({ text: giftFan + ' 送出了 ' + gift.icon + gift.name + ' x' + qty, color: '#ffb060', name: giftFan, isGift: true, isBigGift: gift.value >= 50, ts: Date.now() });
        _showGiftFloat(gift.icon, gift.name, giftFan, qty);
        /* 大额礼物触发打赏任务 */
        if (gift.value * qty >= 50) {
          (function(gName, gVal, fName) {
            setTimeout(function() {
              if (_liveState) _triggerDailyTask(gName, gVal, fName);
            }, 1500);
          })(gift.name, gift.value * qty, giftFan);
        }
      }

      /* 随机翻车事件 */
      var pop3 = _v('user.人气', 0);
      var incidentChance = 0.008 + pop3 / 5000; /* 人气越高越容易翻车 */
      if (_liveState && !_liveState.incidentCooldown && Math.random() < incidentChance) {
        _liveState.incidentCooldown = true;
        var incTypes = ['hater', 'warning', 'screenshot', 'bigfan'];
        var incWeights = [40, 25, 25, 10]; /* hater最多，bigfan最少 */
        var roll = Math.random() * 100, acc = 0, picked = 'hater';
        for (var ii = 0; ii < incTypes.length; ii++) { acc += incWeights[ii]; if (roll < acc) { picked = incTypes[ii]; break; } }
        /* 榜一大哥事件需要有人气基础 */
        if (picked === 'bigfan' && pop3 < 30) picked = 'hater';
        setTimeout(function() { _triggerLiveIncident(picked); }, 500);
        setTimeout(function() { if (_liveState) _liveState.incidentCooldown = false; }, 60000); /* 1分钟冷却 */
      }

      /* 艺人进入：走API读人设+上下文 */
      if (Math.random() < cfg.actorChance) {
        var candidates = [];
        for (var co in COMPANIES) {
          var acts = COMPANIES[co].actors;
          for (var ai = 0; ai < acts.length; ai++) {
            var an = acts[ai];
            if (_liveState.actorVisited[an]) continue;
            var ad = _v('艺人.' + co + '.' + an, {});
            var fv = ad['\u597d\u611f\u5ea6'] || 0;
            if (fv >= 30 && Math.random() < (fv / 200)) candidates.push(an);
          }
        }
        if (candidates.length) {
          var picked = candidates[Math.floor(Math.random()*candidates.length)];
          _liveState.actorVisited[picked] = true;
          var actorColor = (USER_CONFIG.actorColors && USER_CONFIG.actorColors[picked]) || '#e0e0e0';
          _addDanmaku('进入了直播间', actorColor, false, picked);
          (function(actorName, color) {
            setTimeout(async function() {
              if (!_liveState) return;
              var line = await _genActorLiveLine(actorName);
              if (!line) {
                var persona = await _fetchActorPersona(actorName);
                if (persona && persona.indexOf('沉默') >= 0) line = '……';
                else if (persona && persona.indexOf('话痨') >= 0) line = '哎呀来晚了，今天怎么样？';
                else if (persona && persona.indexOf('冷') >= 0) line = '嗯。';
                else line = '来看看';
              }
              _addDanmaku(line, color, false, actorName);
              /* 艺人有概率刷礼物 */
              if (Math.random() < 0.45) {
                var actorGift = _LIVE_GIFTS[Math.floor(Math.random() * 4) + 1];
                var actorQty = actorGift.value <= 10 ? Math.floor(Math.random()*3)+1 : 1;
                _addDanmaku('送出了 ' + actorGift.icon + actorGift.name + ' x' + actorQty, '#ffb060', true, actorName);
                _liveState.coins += actorGift.value * actorQty;
                _showGiftFloat(actorGift.icon, actorGift.name, actorName, actorQty);
              }
              _renderLiveDanmaku();
            }, 2000 + Math.random()*3000);
          })(picked, actorColor);
        }
      }

      _renderLiveDanmaku();

      var nextDelay = cfg.interval[0] + Math.random() * (cfg.interval[1] - cfg.interval[0]);
      _liveState.timer = setTimeout(_tickDanmaku, nextDelay);
    }

    function _triggerDailyTask(giftName, giftValue, fanName) {
      /* 找匹配的任务 */
      var candidates = _LIVE_DAILY_TASKS.filter(function(t2) { return t2.gift === giftName && giftValue >= t2.minValue; });
      if (!candidates.length) return;
      var task = candidates[Math.floor(Math.random() * candidates.length)];

      var t3 = _t();
      var d = '';
      d += '<div style="text-align:center;font-size:28px;margin-bottom:6px">🎁</div>';
      d += '<div style="font-size:12px;font-weight:700;color:#ffb060;text-align:center;margin-bottom:8px">' + _esc(fanName) + ' 的打赏任务</div>';
      d += '<div style="font-size:10px;color:' + t3.text + ';text-align:center;line-height:1.7;margin-bottom:12px;padding:10px;background:rgba(255,176,96,.08);border-radius:10px;border:1px solid rgba(255,176,96,.25)">' + _esc(task.task) + '</div>';
      d += '<div style="font-size:9px;color:' + t3.textDim + ';line-height:1.7;margin-bottom:10px">';
      d += '💰 奖励：' + task.coins + ' 金币 · ⭐ 人气+' + task.popGain;
      if (task.risk > 0) d += '<br><span style="color:#ff6060">⚠️ 风险：有' + task.risk + '%概率被截图/举报，触发平台警告</span>';
      d += '</div>';
      d += '<div class="av-dlg-actions">';
      d += '<button class="av-dlg-btn av-dlg-cancel" id="av-task-reject">拒绝</button>';
      d += '<button class="av-dlg-btn av-dlg-ok" id="av-task-accept" style="background:rgba(255,176,96,.2);border-color:rgba(255,176,96,.5);color:#ffb060">接受</button>';
      d += '</div>';

      var w = _dialog(d);

      w.find('#av-task-reject').on('click', function() {
        w.remove();
        _addDanmaku('（拒绝了 ' + fanName + ' 的任务）', 'rgba(255,100,100,.7)', false, '我', true);
        _renderLiveDanmaku();
        /* 拒绝掉人气 */
        if (_liveState) _liveState.interactCount -= 1;
      });

      w.find('#av-task-accept').on('click', function() {
        w.remove();
        _addDanmaku('（接受了 ' + fanName + ' 的任务：' + task.task + '）', 'rgba(255,176,96,.9)', false, '我', true);
        /* 执行动作，触发反应 */
        _liveAction($('#' + G.elIds.overlay), task.act);
        /* 奖励 */
        if (_liveState) _liveState.coins += task.coins;
        /* 风险判定 */
        if (task.risk > 0 && Math.random() * 100 < task.risk) {
          setTimeout(function() {
            _triggerLiveIncident('screenshot');
          }, 2000);
        }
      });
    }

