          var _dtxt = d.text || '';
          if (_dtxt.length > 30) _dtxt = _dtxt.substring(0, 30) + '…';
          /* 兜底：结尾是残句标点就丢掉 */
          if (/[，、,。；;：:]$/.test(_dtxt)) _dtxt = _dtxt.substring(0, _dtxt.length - 1);
