      d += '<div style="font-size:22px;font-weight:900;color:' + (rating === 'S' ? '#ffb060' : rating === 'A' ? '#ffd060' : rating === 'D' ? '#ff6060' : '#50c878') + ';letter-spacing:2px;margin-bottom:6px">' + rating + ' 级直播</div>';
