      d += '<div style="display:flex;justify-content:space-between;font-size:10px;padding:4px 0"><span style="color:' + t.textDim + '">💰 直播收入</span><span style="color:#ffb060;font-weight:600">+' + earnedCoins + ' 金币</span></div>';
      d += '<div style="display:flex;justify-content:space-between;font-size:10px;padding:4px 0"><span style="color:' + t.textDim + '">⭐ 人气变化</span><span style="color:#50c878;font-weight:600">+' + popGain + '</span></div>';
      d += '<div style="display:flex;justify-content:space-between;font-size:10px;padding:4px 0"><span style="color:' + t.textDim + '">👥 涨粉数</span><span style="color:#60b0e0;font-weight:600">+' + fanGains + '</span></div>';
      d += '<div style="display:flex;justify-content:space-between;font-size:10px;padding:4px 0"><span style="color:' + t.textDim + '">🔥 热度值</span><span style="color:' + (hotSearch ? '#ff3b30' : t.text) + ';font-weight:600">' + heat + (hotSearch ? ' 🔥' : '') + '</span></div>';
      d += '<div style="display:flex;justify-content:space-between;font-size:10px;padding:4px 0"><span style="color:' + t.textDim + '">💬 互动次数</span><span style="color:' + t.text + ';font-weight:600">' + interact + '</span></div>';
      if (topFan) {
        d += '<div style="display:flex;justify-content:space-between;font-size:10px;padding:4px 0;border-top:1px solid ' + t.divider + ';margin-top:4px;padding-top:8px"><span style="color:' + t.textDim + '">👑 榜一大哥</span><span style="color:#ffb060;font-weight:600">' + _esc(topFan) + ' (' + topCount + '个礼物)</span></div>';
      }
