      d += '<div class="av-dlg-actions"><button class="av-dlg-btn av-dlg-cancel" id="av-live-no-report" style="flex:1">直接下播</button><button class="av-dlg-btn av-dlg-ok" id="av-live-end-ok" style="flex:1">发送结算</button></div>';

      var w = _dialog(d);
