        report += '收入' + earnedCoins + '金币，人气+' + popGain + '，涨粉+' + fanGains + '，热度值' + heat + '。';
        if (topFan) report += '榜一大哥是' + topFan + '（送出' + topCount + '个礼物）。';
        if (hotSearch) report += '热度值爆表，登上了微博热搜。';
        report += '请更新我的金币、人气、粉丝数据' + (hotSearch ? '，并在报纸或微博板块加入这次直播上热搜的新闻' : '') + '。';
        if (typeof triggerSlash === 'function') triggerSlash('/send ' + report + ' | /trigger');
