      /* ═══ 长按会话 → 菜单 ═══ */
      var _convTimer = null, _convTriggered = false;
      $c.off('touchstart mousedown', '.av-sms-list-item')
        .on('touchstart mousedown', '.av-sms-list-item', function(e) {
          var $el = $(this);
          _convTriggered = false;
          _convTimer = setTimeout(function() {
            _convTriggered = true;
            _showConvActionMenu($c, $el.data('contact'));
          }, 500);
        });
      $c.off('touchend mouseup mouseleave', '.av-sms-list-item')
        .on('touchend mouseup mouseleave', '.av-sms-list-item', function() {
          if (_convTimer) { clearTimeout(_convTimer); _convTimer = null; }
        });

      /* ═══ "+"按钮切换面板 ═══ */
      $c.find('#av-sms-plus-btn').on('click', function() {
        var $sp = $('#av-sms-sticker-panel');
        var $pp = $('#av-sms-plus-panel');
        if ($pp.is(':visible')) { $pp.hide(); }
        else { $sp.hide(); $pp.show(); }
      });

      /* ═══ "+"面板功能 ═══ */
      $c.find('.av-sms-plus-item').on('click', function() {
        var act = $(this).data('act');
        $('#av-sms-plus-panel').hide();

        /* 本地导入图片 */
        if (act === 'image-local') {
          _pickSmsImage(function(url) {
            if (!url || !_commContact) return;
            var data = _loadSmsData();
            if (!data[_commContact]) data[_commContact] = [];
            data[_commContact].push({ from: 'user', text: url, type: 'image', ts: Date.now() });
            _saveSmsData(data);
            _drawComm($c);
            /* AI 回应 */
            _handleSmsImageReply($c, '图片', '[玩家发了一张图片]');
          });
          return;
        }

        /* AI 生图 */
        if (act === 'image-ai') {
          var imgApi = _loadImgApi();
          if (!imgApi || !imgApi.endpoint || !imgApi.key) {
            if (typeof triggerSlash === 'function') triggerSlash('/echo severity=warning ⚠️ 请先配置生图 API（API APP → 生图 API）');
            return;
          }
          _showSmsImageAIDialog($c);
          return;
        }

        /* 位置分享 */
        if (act === 'location') {
          _showSmsLocationDialog($c);
          return;
        }

        /* 红包 */
        if (act === 'hongbao') {
          _showSmsHongbaoDialog($c);
          return;
        }

        /* 转账 */
        if (act === 'transfer') {
          _showSmsTransferDialog($c);
          return;
        }

        /* 语音（暂不实现） */
        if (act === 'voice') {
          if (typeof triggerSlash === 'function') triggerSlash('/echo severity=info 语音功能开发中');
          return;
        }
      });

      /* 短信表情按钮 */
