      scored.sort(function (a, b) { return b.score - a.score; });
      var top = scored.slice(0, 3);

      var d = '<div class="av-dlg-h">👔 ' + _esc(mgrName) + '的推荐</div>';
      d += '<div style="font-size:8px;color:' + t.textMuted + ';margin-bottom:8px">偏好标签：' + prefs.map(_esc).join('、') + '</div>';
