/* ═══ 影视市场界面 ═══ */
function _drawFilmScripts($c) {
  var t = _t();
  var scripts = _loadFilmCache();
  var o = '';

  /* 顶栏 */
  o += '<div style="display:flex;justify-content:space-between;align-items:center;padding:6px 2px;margin-bottom:6px">';
  o += '<div style="font-size:8px;color:' + t.textMuted + '">🎞️ 影视 · 共 ' + scripts.length + ' 个项目</div>';
  o += '<div style="display:flex;gap:4px">';
  o += '<button class="av-dlg-btn av-dlg-ok" id="av-film-directors" style="font-size:8px;padding:4px 12px;background:rgba(160,120,220,.12);border-color:rgba(160,120,220,.3);color:#b090e0">🎬 选角导演</button>';
  o += '<button class="av-dlg-btn av-dlg-ok" id="av-film-refresh" style="font-size:8px;padding:4px 12px">' + (scripts.length ? '🔄 刷新' : '✨ 生成项目') + '</button>';
  o += '</div>';
  o += '</div>';

  /* 说明 */
  o += '<div style="font-size:8px;color:' + t.textMuted + ';margin-bottom:10px;text-align:center;font-style:italic">💡 影视项目需要先试镜，通过后才能拿到角色</div>';

  if (!scripts.length) {
    o += '<div class="av-nil">暂无影视项目<br><span style="font-size:8px;opacity:.6">点击上方按钮生成</span></div>';
  } else {
    o += '<div style="display:grid;grid-template-columns:repeat(2,1fr);gap:8px">';
    for (var si = 0; si < scripts.length; si++) {
      var s = scripts[si];
      var ft = FILM_TYPES[s.filmType] || FILM_TYPES['movie'];
      var mTag = s.tags[0] || '剧情';
      var mColor = TAG_COLORS_FILM[mTag] || '#5080d0';

      o += '<div class="av-film-card" data-idx="' + si + '" style="border-radius:14px;overflow:hidden;cursor:pointer;border:1px solid ' + t.border + '">';
      o += '<div style="width:100%;aspect-ratio:3/4;background:linear-gradient(135deg,' + mColor + '44,' + mColor + '11);position:relative;padding:10px;box-sizing:border-box;display:flex;flex-direction:column;justify-content:flex-end">';
      o += '<div style="position:absolute;inset:0;background:linear-gradient(transparent 45%,rgba(0,0,0,.9) 100%)"></div>';
      /* 左上角：类型 */
      o += '<div style="position:absolute;top:6px;left:6px;font-size:7px;padding:2px 7px;border-radius:6px;background:' + ft.color + 'dd;color:#fff;font-weight:700;z-index:1">' + ft.icon + ' ' + ft.name + '</div>';
      /* 右上角：集数 + 报酬 */
      o += '<div style="position:absolute;top:6px;right:6px;font-size:6px;color:#ffb060;z-index:1;background:rgba(0,0,0,.5);padding:2px 6px;border-radius:6px;text-align:right;line-height:1.3">' + (s.episodes > 1 ? s.episodes + '集<br>' : '') + '💰' + s.reward + '</div>';
      /* 底部 */
      o += '<div style="position:relative;z-index:1">';
      o += '<div style="display:flex;gap:3px;margin-bottom:4px;flex-wrap:wrap">';
      var _ptc = s.pairType === 'BL' ? '#5080d0' : (s.pairType === 'GL' ? '#e05080' : (s.pairType === 'BG' ? '#c8a040' : (s.pairType === 'GB' ? '#9070c0' : '#a0a0a0')));
      o += '<span style="font-size:7px;padding:2px 7px;border-radius:6px;background:' + _ptc + 'dd;color:#fff;font-weight:700">' + _esc(s.pairType || '') + '</span>';
      var roleColor = s.role === '主角' ? '#e05080' : (s.role === '配角' ? '#c8a040' : '#808080');
      o += '<span style="font-size:7px;padding:2px 7px;border-radius:6px;background:' + roleColor + 'dd;color:#fff;font-weight:700">' + _esc(s.role || '主角') + '</span>';
      if (s.passed) o += '<span style="font-size:7px;padding:2px 7px;border-radius:6px;background:#50c878dd;color:#fff;font-weight:700">✓ 已过试镜</span>';
      o += '</div>';
      o += '<div style="font-size:11px;font-weight:700;color:#fff;text-shadow:0 1px 4px rgba(0,0,0,.5);line-height:1.3;margin-bottom:2px">' + _esc(s.title) + '</div>';
      o += '<div style="font-size:7px;color:rgba(255,255,255,.6)">' + s.actors.map(_esc).join(' · ') + '</div>';
      o += '</div></div></div>';
    }
    o += '</div>';
  }

  $c.html(o);

  /* 选角导演列表 */
  $c.find('#av-film-directors').on('click', function() {
    _showCastingDirectorsDialog();
  });

  $c.find('#av-film-refresh').on('click', async function() {
    var $btn = $(this);
    $btn.prop('disabled', true).text('生成中...');
    if (typeof triggerSlash === 'function') triggerSlash('/echo severity=info 正在生成影视项目...');
    var ns = await _genFilmScripts();
    if (ns.length) {
      _saveFilmCache(ns);
      if (typeof triggerSlash === 'function') triggerSlash('/echo severity=success 已生成' + ns.length + '个影视项目');
    } else {
      if (typeof triggerSlash === 'function') triggerSlash('/echo severity=warning 生成失败，请检查辅助API');
    }
    _drawFilmScripts($c);
  });

  $c.find('.av-film-card').on('click', function() {
    /* ═══ 电视剧/网剧拍摄中，锁定 ═══ */
    var _lockScr3 = _getCurScr();
    if (_lockScr3 && (_lockScr3.filmType === 'tv' || _lockScr3.filmType === 'web')) {
      var _lockE3 = _lockScr3.currentEpisode || 1;
      var _lockT3 = _lockScr3.totalEpisodes || _lockScr3.episodes || 1;
      if (_lockE3 < _lockT3) {
        if (typeof triggerSlash === 'function') triggerSlash('/echo severity=warning 电视剧《' + _lockScr3.title + '》还在拍摄中（第' + _lockE3 + '/' + _lockT3 + '集），不能接新剧本');
        return;
      }
    }
    var idx = parseInt($(this).data('idx'));
    var scr = _loadFilmCache()[idx];
    if (!scr) return;
    _showFilmScriptDetail(scr, idx, $c);
  });
}

/* ═══ 选角导演列表弹窗 ═══ */
function _showCastingDirectorsDialog() {
  var t = _t();
  var d = '';
  d += '<div class="av-dlg-h">🎬 选角导演</div>';
  d += '<div class="av-dlg-sub">试镜通过率受他们好感影响</div>';

  /* 按好感从高到低排序 */
  var list = [];
  for (var dName in CASTING_DIRECTORS) {
    list.push({ name: dName, favor: _getCastingFavor(dName) });
  }
  list.sort(function(a, b) { return b.favor - a.favor; });

  d += '<div style="max-height:380px;overflow-y:auto;margin-top:8px">';
  for (var i = 0; i < list.length; i++) {
    var item = list[i];
    var cd = CASTING_DIRECTORS[item.name];
    var favor = item.favor;
    var blocked = favor <= -10;
    var canSkip = favor >= 30;

    var favorColor = blocked ? '#ff3b30' : (canSkip ? '#50c878' : (favor > 0 ? '#ffb060' : t.textMuted));
    var favorText = blocked ? '⛔ 已拉黑' : (canSkip ? '✨ 可直通' : (favor > 20 ? '关系好' : (favor > 0 ? '有好感' : (favor < 0 ? '印象差' : '中立'))));

    d += '<div style="display:flex;align-items:flex-start;gap:10px;padding:10px;border-radius:12px;margin-bottom:6px;background:' + (blocked ? 'rgba(255,60,48,.06)' : (canSkip ? 'rgba(80,200,120,.06)' : t.surfaceHover)) + ';border:1px solid ' + (blocked ? 'rgba(255,60,48,.2)' : (canSkip ? 'rgba(80,200,120,.2)' : t.border)) + ';' + (blocked ? 'opacity:.7' : '') + '">';

    /* 头像 */
    d += '<div style="width:40px;height:40px;border-radius:50%;flex-shrink:0;display:flex;align-items:center;justify-content:center;font-size:20px;background:' + (blocked ? '#ff3b3022' : (canSkip ? '#50c87822' : t.iconBg)) + '">' + (cd.icon || '🎬') + '</div>';

    d += '<div style="flex:1;min-width:0">';
    /* 名字 + 风格 */
    d += '<div style="display:flex;align-items:center;gap:6px;flex-wrap:wrap;margin-bottom:2px">';
    d += '<span style="font-size:12px;font-weight:600;color:' + (blocked ? t.textMuted : t.text) + '">' + _esc(item.name) + '</span>';
    d += '<span style="font-size:7px;padding:1px 6px;border-radius:6px;background:rgba(' + t.primaryRgb + ',.1);color:' + t.primary + '">' + _esc(cd.style) + '</span>';
    d += '<span style="font-size:9px;font-weight:700;color:' + favorColor + ';margin-left:auto">' + (favor > 0 ? '+' : '') + favor + ' · ' + favorText + '</span>';
    d += '</div>';
    /* 描述 */
    d += '<div style="font-size:8px;color:' + t.textDim + ';line-height:1.5;margin-bottom:4px">' + _esc(cd.desc) + '</div>';
    /* 偏好标签 */
    d += '<div style="display:flex;flex-wrap:wrap;gap:3px">';
    for (var ti = 0; ti < cd.preferTags.length; ti++) {
      var ptag = cd.preferTags[ti];
      var ptc = TAG_COLORS_FILM[ptag] || t.textMuted;
      d += '<span style="font-size:6px;padding:1px 5px;border-radius:5px;background:' + ptc + '22;color:' + ptc + '">' + _esc(ptag) + '</span>';
    }
    d += '</div>';
    d += '</div></div>';
  }
  d += '</div>';

  d += '<div class="av-dlg-actions"><button class="av-dlg-btn av-dlg-cancel" id="av-cd-close">关闭</button></div>';

  var w = _dialog(d);
  w.find('#av-cd-close').on('click', function() { w.remove(); });
}

