  function _handleBlackmatChoice(act, eventId, cost) {
    var coins = _v('user.金币', 0);

    if (act === 'pr') {
      if (coins < cost) {
        if (typeof triggerSlash === 'function') triggerSlash('/echo severity=warning 金币不足，需要💰' + cost);
        return;
      }
      if (typeof triggerSlash === 'function') {
        triggerSlash('/send 我找了顶级公关公司处理「' + eventId + '」这条黑料，花费' + cost + '金币。请演绎公关团队的操作过程（联系媒体、删除爆料、买通水军、发通稿等），并判定结果（80%成功压下）。更新 user.黑料记录.' + eventId + '.状态 为"已解决"或"已发酵"，应对方式填"公关"。成功后 user.八卦值 -15，user.人气 +3；失败则 user.八卦值 +10。 | /trigger');
      }
      return;
    }

    if (act === 'clarify') {
      var success = Math.random() < 0.5;
      if (typeof triggerSlash === 'function') {
        var msg = '我发了正式声明澄清「' + eventId + '」。';
        if (success) {
          msg += '声明获得公众认可，舆论反转。请演绎发声明后的过程和外界反应。更新 user.黑料记录.' + eventId + '.状态 为"已解决"，应对方式填"澄清"。user.八卦值 -10，user.人气 +5。';
        } else {
          msg += '声明被认为是洗白，反而引发网友继续扒皮，曝出更多黑料。请演绎翻车过程。更新 user.黑料记录.' + eventId + '.状态 为"已发酵"，应对方式填"澄清失败"。user.八卦值 +15，user.人气 -10，可能触发新的黑料。';
        }
        triggerSlash('/send ' + msg + ' | /trigger');
      }
      return;
    }

    if (act === 'ignore') {
      if (typeof triggerSlash === 'function') {
        triggerSlash('/send 我对「' + eventId + '」这条黑料选择装死冷处理，不作回应。请演绎几天后风波自然消退的过程，但同时写清楚对我事业的影响（粉丝流失、资源减少、公司态度等）。更新 user.黑料记录.' + eventId + '.状态 为"已解决"，应对方式填"装死"。user.人气 -15，user.名气 -5，user.八卦值 -5（风波消退）。 | /trigger');
      }
      return;
    }

    if (act === 'counter') {
      var reverse = Math.random() < 0.3;
      if (typeof triggerSlash === 'function') {
        var msg2 = '我决定反咬对方，公开爆料者的黑历史。';
        if (reverse) {
          msg2 += '舆论成功反转，大众开始同情我。请演绎反转过程。更新 user.黑料记录.' + eventId + '.状态 为"已解决"，应对方式填"反咬成功"。user.八卦值 +5，user.人气 +10。';
        } else {
          msg2 += '反咬被认为恼羞成怒，火上浇油，舆论彻底失控。请演绎翻车过程。更新 user.黑料记录.' + eventId + '.状态 为"已发酵"，应对方式填"反咬失败"。user.八卦值 +25，user.人气 -20，user.名气 -10，可能触发公司施压或解约警告。';
        }
        triggerSlash('/send ' + msg2 + ' | /trigger');
      }
      return;
    }
  }

