    o += '<div style="height:6px;background:' + t.trackBg + ';border-radius:3px;overflow:hidden"><div style="height:100%;width:' + stamina + '%;background:' + stamColor + ';border-radius:3px;transition:width .5s"></div></div>';
    o += '</div>';

    /* 疲劳条 */
    var fatColor = fatigue < 40 ? '#50c878' : (fatigue < 80 ? '#ffb060' : '#ff6060');
    o += '<div style="margin-bottom:10px">';
