    o += '<div style="height:6px;background:' + t.trackBg + ';border-radius:3px;overflow:hidden"><div style="height:100%;width:' + fatigue + '%;background:' + fatColor + ';border-radius:3px;transition:width .5s"></div></div>';
    o += '</div>';

