    o += '<div style="height:6px;background:' + t.trackBg + ';border-radius:3px;overflow:hidden"><div style="height:100%;width:' + stress + '%;background:' + strColor + ';border-radius:3px;transition:width .5s"></div></div>';
    o += '</div>';

    /* 怀孕状态 */
    var pregText = { '无': '未怀孕', '疑似': '⚠️ 月经推迟，可能怀孕', '已确认': '🔴 已确认怀孕', '已处理': '已处理' }[pregnancy] || '未知';
    var pregColor = pregnancy === '已确认' ? '#ff3b30' : (pregnancy === '疑似' ? '#ffb060' : t.textMuted);
    o += '<div style="display:flex;justify-content:space-between;font-size:9px;padding:6px 0;border-top:1px solid ' + t.divider + '"><span style="color:' + t.textDim + '">🤰 怀孕状态</span><span style="color:' + pregColor + ';font-weight:600">' + pregText + '</span></div>';

    /* 避孕状态 */
