    /* 上次体检 */
    var checkupText = lastCheckup === 0 ? '从未体检' : ('第' + lastCheckup + '周');
    var checkupWarn = (curWeek - lastCheckup) > 4 && lastCheckup > 0;
    o += '<div style="display:flex;justify-content:space-between;font-size:9px;padding:6px 0;border-top:1px solid ' + t.divider + '"><span style="color:' + t.textDim + '">📋 上次体检</span><span style="color:' + (checkupWarn ? '#ffb060' : t.textMuted) + ';font-weight:600">' + checkupText + (checkupWarn ? ' ⚠️ 建议体检' : '') + '</span></div>';

    o += '</div>';

