    /* 成就 */
    'av-achievements-done',
    /* 官宣系统 */
    'av-public-state',
    'av-public-cooldown',
    'av-doggy-watch',
    /* 吃醋系统 */
    'av-jealous-state',
    'av-jealous-cooldown',
    /* 纪念日系统 */
