  /* 顾临渊 走中性：孤僻，要找"真实的人"，好感≥90 才算认了 */

  /* 判断某个角色是否接受 NP */
  function _isNPOk(charName) {
    if (!charName) return false;

    /* ── 第一步：传统型明确拒绝 ── */
    if (NP_TRADITIONAL_ACTORS.indexOf(charName) >= 0) return false;
    if (NP_TRADITIONAL_MANAGERS.indexOf(charName) >= 0) return false;
    if (NP_TRADITIONAL_BOSSES.indexOf(charName) >= 0) return false;

    /* ── 第二步：开放型明确接受 ── */
    if (NP_OPEN_ACTORS.indexOf(charName) >= 0) return true;
    if (NP_OPEN_MANAGERS.indexOf(charName) >= 0) return true;
    if (NP_OPEN_BOSSES.indexOf(charName) >= 0) return true;

    /* ── 第三步：中性角色，看好感度（≥90 勉强接受） ── */
    var favor = _getCharFavor(charName);
    return favor >= 90;
  }

  /* 通用：读取任意角色（艺人/经纪人/老板）的好感度 */
  function _getCharFavor(charName) {
    if (!charName) return 0;

    /* 艺人 */
    var co = _getActorCompany(charName);
    if (co && co !== '未知') {
      return _v('艺人.' + co + '.' + charName + '.好感度', 0);
    }

    /* 经纪人 */
    if (charName === _v('经纪人.姓名', '')) {
      return _v('经纪人.好感度', 0);
    }

    /* 老板 */
    var bossFavor = _v('老板.' + charName + '.好感度', 0);
    if (bossFavor > 0) return bossFavor;

    return 0;
  }

  /* ═══ 统一关系读取 ═══ */
  /* 返回：{ spouse: 'xxx'|null, affairs: ['a','b'], all: ['spouse','a','b'] } */
  function _loadRelations() {
    var result = { spouse: null, affairs: [], all: [] };
    /* 找已婚配偶（从 wedding-state 里找 married=true 的） */
    var wState = _loadWeddingState();
    for (var wn in wState) {
      if (wState[wn] && wState[wn].married) {
        result.spouse = wn;
        break;
      }
    }
    /* 找恋爱对象（从 confession-state 里找 triggered=true 的，排除配偶） */
    var cState = _loadConfessionState();
    for (var cn in cState) {
      if (cState[cn] && cState[cn].triggered && cn !== result.spouse) {
        result.affairs.push(cn);
      }
    }
    if (result.spouse) result.all.push(result.spouse);
    result.all = result.all.concat(result.affairs);
    return result;
  }

  /* 判断某角色是不是玩家的恋爱对象（不含配偶） */
  function _hasAffairWith(name) {
    var rel = _loadRelations();
    return rel.affairs.indexOf(name) >= 0;
  }

  /* 列出所有恋爱对象（不含配偶） */
  function _getAffairPartners() {
    return _loadRelations().affairs;
  }

  /* 读取告白状态 */
  function _loadConfessionState() {
    try {
      var r = localStorage.getItem(CONFESSION_KEY);
      if (r) return JSON.parse(r);
    } catch (e) {}
    return {};
  }

  /* 写入告白状态 */
  function _saveConfessionState(state) {
    try {
      localStorage.setItem(CONFESSION_KEY, JSON.stringify(state));
    } catch (e) {}
  }

  /* 获取单个角色的告白状态 */
  function _getConfessionState(name) {
    var s = _loadConfessionState();
    return s[name] || { triggered: false, triggeredWeek: 0, postponed: 0, missed: false };
  }

  /* 更新单个角色的告白状态 */
  function _setConfessionState(name, patch) {
    var s = _loadConfessionState();
    if (!s[name]) s[name] = { triggered: false, triggeredWeek: 0, postponed: 0, missed: false };
    for (var k in patch) {
      if (patch.hasOwnProperty(k)) s[name][k] = patch[k];
    }
    _saveConfessionState(s);
  }

