    var idDesc = '';
    if (type === 'manager') {
      idLabel = '【经纪人】';
      idDesc = ta + '最近总是心不在焉，推掉了好几个能赚钱的商务。';
    } else if (type === 'boss') {
      idLabel = '【老板】';
      idDesc = ta + '最近一反常态，经常问你些和工作无关的事。';
    } else {
      idLabel = '';
      idDesc = ta + '推掉了几个工作，' + degree + '频繁去' + _esc(place) + '。';
    }

    var d = '';
    d += '<div style="text-align:center;font-size:28px;margin-bottom:6px">📩</div>';
    d += '<div style="font-size:13px;font-weight:700;color:' + t.text + ';text-align:center;margin-bottom:12px">一条匿名消息</div>';

    d += '<div style="font-size:10px;color:' + t.textDim + ';line-height:1.9;padding:12px;background:' + t.surfaceHover + ';border-radius:10px;border-left:3px solid ' + t.primary + ';margin-bottom:12px;white-space:pre-wrap">';
    d += '你最近注意到，' + _esc(actorName) + idLabel + '有点反常。\n';
    d += idDesc + '\n';
    d += ta + '好像……在准备什么。';
    d += '</div>';

    d += '<div style="display:flex;flex-direction:column;gap:6px">';

    /* 选项 A：我去看看 */
    d += '<div class="av-conf-go" style="padding:12px;border-radius:10px;cursor:pointer;background:rgba(224,80,128,.1);border:1px solid rgba(224,80,128,.3);transition:background .15s">';
    d += '<div style="font-size:11px;font-weight:600;color:' + t.primary + '">💗 我去看看</div>';
    d += '<div style="font-size:8px;color:' + t.textMuted + ';margin-top:2px">前往' + _esc(place) + '，看看' + ta + '在准备什么</div>';
    d += '</div>';

    /* 选项 B：先不管 */
    var postponeHint = st_postpone_hint(actorName);
    d += '<div class="av-conf-skip" style="padding:12px;border-radius:10px;cursor:pointer;background:' + t.surfaceHover + ';border:1px solid ' + t.border + ';transition:background .15s">';
    d += '<div style="font-size:11px;font-weight:600;color:' + t.textDim + '">🤷 先不管</div>';
    d += '<div style="font-size:8px;color:' + t.textMuted + ';margin-top:2px">' + postponeHint + '</div>';
    d += '</div>';

    d += '</div>';

    var w = _dialog(d);

    w.find('.av-conf-go').on('click', function() {
      w.remove();
      _triggerConfession(actorName, place, type);
    });

    w.find('.av-conf-skip').on('click', function() {
      w.remove();
      _postponeConfession(actorName, type);
    });
