  /* 推迟提示文案 */
  function st_postpone_hint(actorName) {
    var st = _getConfessionState(actorName);
    var nextCount = (st.postponed || 0) + 1;
    if (nextCount >= 3) return '（这是最后一次机会，错过就没了）';
    return '（好感度-3，' + (nextCount >= 2 ? '下次可能就来不及了' : '过阵子再说吧') + '）';
  }

