    _setConfessionState(actorName, {
      triggered: true,
      triggeredWeek: curWeek,
      postponed: 0,
      missed: false
    });

    /* ═══ 立即记录告白纪念日的起点 ═══ */
    _recordMemoryDate(actorName, 'confession', curWeek);

    /* 全局冷却 */
    _markConfessionCooldown(curWeek);

