  /* ═══════════════════════════════════════
     📢 官宣 / 公开恋情系统
     ═══════════════════════════════════════ */
  var PUBLIC_KEY = 'av-public-state';
  var PUBLIC_COOLDOWN_KEY = 'av-public-cooldown';
  var DOGGY_WATCH_KEY = 'av-doggy-watch';   /* 官宣后24h狗仔盯梢 */

  function _loadPublicState() {
    try { var r = localStorage.getItem(PUBLIC_KEY); if (r) return JSON.parse(r); } catch (e) {}
    return {};
  }
  function _savePublicState(s) {
    try { localStorage.setItem(PUBLIC_KEY, JSON.stringify(s)); } catch (e) {}
  }
  function _getPublicState(name) {
    var s = _loadPublicState();
    return s[name] || { public: false, publicWeek: 0, method: '', denyCount: 0 };
  }
  function _setPublicState(name, patch) {
    var s = _loadPublicState();
    if (!s[name]) s[name] = { public: false, publicWeek: 0, method: '', denyCount: 0 };
    for (var k in patch) { if (patch.hasOwnProperty(k)) s[name][k] = patch[k]; }
    _savePublicState(s);
  }

  /* 全局冷却：一周只允许官宣一个对象 */
  function _checkPublicCooldown(curWeek) {
    var last = 0;
    try { last = parseInt(localStorage.getItem(PUBLIC_COOLDOWN_KEY) || '0'); } catch (e) {}
    if (last > 0 && (curWeek - last) < 2) return false;
    return true;
  }
  function _markPublicCooldown(curWeek) {
    try { localStorage.setItem(PUBLIC_COOLDOWN_KEY, String(curWeek)); } catch (e) {}
  }

  /* 官宣后 24h（本游戏用「本周+下周」近似）狗仔盯梢 */
  function _isDoggyWatching() {
    try {
      var w = JSON.parse(localStorage.getItem(DOGGY_WATCH_KEY) || 'null');
      if (!w) return false;
      var curWeek = _v('user.当前时间.周数', 1);
      return curWeek <= w.untilWeek;
    } catch (e) { return false; }
  }
  function _startDoggyWatch() {
    var curWeek = _v('user.当前时间.周数', 1);
    try {
      localStorage.setItem(DOGGY_WATCH_KEY, JSON.stringify({ untilWeek: curWeek + 1, startWeek: curWeek }));
    } catch (e) {}
  }

  /* 该角色是否是可以官宣的对象（恋人/配偶） */
  function _canGoPublic(name) {
    if (!name) return false;
    var rel = _loadRelations();
    if (rel.spouse === name) return true;
    if (rel.affairs.indexOf(name) >= 0) return true;
    return false;
  }

  /* 已被官宣过的角色 */
  function _isAlreadyPublic(name) {
    return _getPublicState(name).public === true;
  }

