  /* ═══════════════════════════════════════
     💔 吃醋 / 修罗场 · 主动触发
     ═══════════════════════════════════════ */
  var JEALOUS_KEY = 'av-jealous-state';
  var JEALOUS_COOLDOWN_KEY = 'av-jealous-cooldown';

  function _loadJealousState() {
    try { var r = localStorage.getItem(JEALOUS_KEY); if (r) return JSON.parse(r); } catch (e) {}
    return {};
  }
  function _saveJealousState(s) {
    try { localStorage.setItem(JEALOUS_KEY, JSON.stringify(s)); } catch (e) {}
  }
  function _getJealousRecord(name) {
    var s = _loadJealousState();
    return s[name] || { lastWeek: 0, count: 0, muted: false };
  }
  function _setJealousRecord(name, patch) {
    var s = _loadJealousState();
    if (!s[name]) s[name] = { lastWeek: 0, count: 0, muted: false };
    for (var k in patch) { if (patch.hasOwnProperty(k)) s[name][k] = patch[k]; }
    _saveJealousState(s);
  }

  /* 全局冷却：3 周内最多弹一次吃醋短信 */
  function _checkJealousCooldown(curWeek) {
    var last = 0;
    try { last = parseInt(localStorage.getItem(JEALOUS_COOLDOWN_KEY) || '0'); } catch (e) {}
    if (last > 0 && (curWeek - last) < 3) return false;
    return true;
  }
  function _markJealousCooldown(curWeek) {
    try { localStorage.setItem(JEALOUS_COOLDOWN_KEY, String(curWeek)); } catch (e) {}
  }

  /* 找最合适的吃醋候选：返回 { jealous: 吃醋的人, main: 你更亲近的人, gap: 好感差 } */
  function _getJealousCandidate() {
    if (typeof ScenePlayer !== 'undefined' && (ScenePlayer.state.active || ScenePlayer.state.waiting)) return null;

    var curWeek = _v('user.当前时间.周数', 1);
    var rel = _loadRelations();

    /* 找玩家所有高好感对象（恋人 + 暧昧 ≥ 60） */
    var liked = [];
    for (var i = 0; i < ALL_ACTORS.length; i++) {
      var an = ALL_ACTORS[i];
      var co = _getActorCompany(an);
      if (!co || co === '未知') continue;
      var favor = _v('艺人.' + co + '.' + an + '.好感度', 0);
      if (favor >= 60) liked.push({ name: an, favor: favor, company: co });
    }
    /* 经纪人 + 老板也可以参与 */
    var mgrName = _v('经纪人.姓名', '待选择');
    var mgrSigned = _v('经纪人.是否签约', false);
    if (mgrSigned && mgrName && mgrName !== '待选择') {
      var mF = _v('经纪人.好感度', 0);
      if (mF >= 60) liked.push({ name: mgrName, favor: mF, company: '' });
    }
    for (var bossCo in _BOSSES) {
      if (!_BOSSES.hasOwnProperty(bossCo)) continue;
      var boss = _BOSSES[bossCo];
      if (!boss || !boss.name) continue;
      var bF = _v('老板.' + boss.name + '.好感度', 0);
      if (bF >= 60) liked.push({ name: boss.name, favor: bF, company: bossCo });
    }

    if (liked.length < 1) return null;

    /* 对每个人，检查其关联艺人是否吃醋 */
    var candidates = [];
    for (var k = 0; k < liked.length; k++) {
      var main = liked[k];
      var related = _getRelatedActors(main.name);

      for (var r = 0; r < related.length; r++) {
        var jr = related[r];
        if (jr.bonus <= 0) continue;  /* 负关系不触发 */

        var jco = _getActorCompany(jr.name);
        if (!jco || jco === '未知') continue;
        var jfavor = _v('艺人.' + jco + '.' + jr.name + '.好感度', 0);

        /* 吃醋者好感 ≥ 30，且比 main 低 */
        if (jfavor < 30) continue;
        if (jfavor >= main.favor) continue;

        /* 吃醋者不能已经被玩家官宣（否则不算吃醋） */
        if (_isAlreadyPublic(jr.name)) continue;

        /* 吃醋者没被玩家"安抚"过（muted） */
        var rec = _getJealousRecord(jr.name);
        if (rec.muted) continue;

        /* 3 周冷却 */
        if (rec.lastWeek > 0 && (curWeek - rec.lastWeek) < 3) continue;

        /* 已经被玩家承认是恋爱对象（affairs / spouse），不算吃醋 */
        if (rel.affairs.indexOf(jr.name) >= 0) continue;
        if (rel.spouse === jr.name) continue;

        candidates.push({
          jealous: jr.name,
          jealousFavor: jfavor,
          main: main.name,
          mainFavor: main.favor,
          gap: main.favor - jfavor
        });
      }
    }

    if (!candidates.length) return null;

    /* 优先挑好感差最大的（越不平衡越容易吃醋） */
    candidates.sort(function(a, b) { return b.gap - a.gap; });
    return candidates[0];
  }

  /* 主入口：检查是否有吃醋事件 */
  function _checkJealousyActive() {
    if ($('.av-dlg-mask').length) return;

    var curWeek = _v('user.当前时间.周数', 1);
    if (!_checkJealousCooldown(curWeek)) return;

    var cand = _getJealousCandidate();
    if (!cand) return;

    /* 概率触发：好感差越大越容易，30% 基础 */
    var triggerChance = 0.3 + Math.min(0.4, cand.gap / 100);
    if (Math.random() > triggerChance) return;

    _markJealousCooldown(curWeek);

    setTimeout(function() {
      _showJealousSmsDialog(cand);
    }, 2000);
  }

