        if (jPath) msg += '请演绎' + jealousName + '收到我的解释后的反应（' + (jCo && jCo !== '未知' ? '' : '') + '符合性格），并更新 ' + jPath + ' +5。';
        else msg += '请演绎' + jealousName + '收到我的解释后的反应，并更新对应好感度 +5。';
        msg += ' | /trigger';
        triggerSlash('/send ' + msg);
