    d += '</div>';

    /* 预先算好推迟提示 */
    var _acs = _getActorConfessState(name);
    var _nextPostpone = (_acs.postponed || 0) + 1;
    var _hint = _nextPostpone >= 3 ? '（这是最后一次机会了）' : (_nextPostpone >= 2 ? '（下次可能就来不及了）' : '（给' + ta + '一点时间）');

    d += '<div class="av-ac-opt" data-act="postpone" style="padding:12px;border-radius:10px;cursor:pointer;background:' + t.surfaceHover + ';border:1px solid ' + t.border + '">';
