    d += '</div>';

    d += '<div class="av-ac-opt" data-act="reject" style="padding:12px;border-radius:10px;cursor:pointer;background:rgba(255,80,80,.1);border:1px solid rgba(255,80,80,.3)">';
    d += '<div style="font-size:11px;font-weight:600;color:#ff6060">🚫 直接拒绝</div>';
    d += '<div style="font-size:8px;color:' + t.textMuted + ';margin-top:2px">' + _esc(name) + '好感 -10，有 10% 概率永久放弃</div>';
