  /* 处理玩家的选择 */
  function _handleActorConfessChoice(act, name, place, co) {
    var curWeek = _v('user.当前时间.周数', 1);
    var gender = _getConfessionGender(name);
    var ta = gender === '女' ? '她' : '他';
    var favorPath = (co && co !== '未知') ? ('艺人.' + co + '.' + name + '.好感度') : '';

    if (act === 'go') {
      /* 接受：标记状态，走玩家侧告白流程 */
      _setActorConfessState(name, {
        initiated: true,
        initiatedWeek: curWeek,
        accepted: true
      });
      /* 同时标记玩家侧告白状态（这样就不会再触发玩家主动） */
      _setConfessionState(name, {
        triggered: true,
        triggeredWeek: curWeek,
        postponed: 0,
        missed: false,
        actorInitiated: true
      });
      /* 记录告白纪念日 */
      _recordMemoryDate(name, 'confession', curWeek);

      /* 打开等待界面 */
      if (typeof ScenePlayer !== 'undefined' && ScenePlayer.showWaiting) {
        ScenePlayer.showWaiting(place);
      }

      if (typeof triggerSlash === 'function') {
        var msg = '【反向攻略 · 我去赴约】\n' +
          name + '主动约我到' + place + '见面。我答应了。\n' +
          '请根据' + name + '的性格（好感已满，' + ta + '是真心告白），演绎这场告白。\n' +
          '注意：这次是' + name + '主动，' + ta + '是打破关系边界的一方，内心有挣扎也有期待。\n' +
          '不要提前剧透，让剧情自然展开。\n' +
          '这是我与' + name + '的正式告白场景。';
        if (favorPath) msg += '（' + name + '主动告白成功后，好感度可维持在现有值或小幅 +5。）';
        triggerSlash('/send ' + msg + ' | /trigger');
      }
      return;
    }

    if (act === 'postpone') {
      var acs = _getActorConfessState(name);
      var nextCount = (acs.postponed || 0) + 1;
      _setActorConfessState(name, {
        postponed: nextCount,
        missed: nextCount >= 3,
        initiatedWeek: curWeek   /* 记录本次，用于 3 周冷却 */
      });

      if (typeof triggerSlash === 'function') {
        var msg2 = '【反向攻略 · 推迟】' + name + '主动约我见面，我暂时没有答应（说"再等等"）。' +
          '请演绎' + name + '收到我推迟回复后的反应（' + ta + '会失落但还是保持体面）。' +
          (favorPath ? '更新 ' + favorPath + ' -3。' : '');
        if (nextCount >= 3) {
          msg2 += '这是第 3 次推迟，' + name + '已经放弃了。';
        }
        msg2 += ' | /trigger';
        triggerSlash('/send ' + msg2);
      }

      if (nextCount >= 3 && typeof triggerSlash === 'function') {
        triggerSlash('/echo severity=info 你已经第三次推迟' + name + '的邀约了，' + name + '放弃了。');
      }
      return;
    }

    if (act === 'reject') {
      /* 10% 概率永久放弃 */
      var permanent = Math.random() < 0.10;
      _setActorConfessState(name, {
        rejected: true,
        missed: permanent,
        initiatedWeek: curWeek
      });

      if (typeof triggerSlash === 'function') {
        var msg3 = '【反向攻略 · 拒绝】' + name + '主动约我见面并向间接表达了心意，我直接拒绝了。' +
          '请演绎' + name + '被拒绝后的反应（符合' + ta + '的性格，可能平静接受、可能强颜欢笑、可能直接转身离开）。' +
          (favorPath ? '更新 ' + favorPath + ' -10。' : '');
        if (permanent) {
          msg3 += name + '被拒绝后彻底放弃了这段感情。';
        } else {
          msg3 += name + '虽然被拒绝，但' + ta + '可能还会再试一次。';
        }
        msg3 += ' | /trigger';
        triggerSlash('/send ' + msg3);
      }
      return;
    }
  }

  /* ═══════════════════════════════════════
     🤰 婚后怀孕系统联动
     ═══════════════════════════════════════ */
  var PREG_LINK_KEY = 'av-preg-link-state';
  var PREG_CHECK_KEY = 'av-preg-check-week';

  function _loadPregLinkState() {
    try { var r = localStorage.getItem(PREG_LINK_KEY); if (r) return JSON.parse(r); } catch (e) {}
    return {};
  }
  function _savePregLinkState(s) {
    try { localStorage.setItem(PREG_LINK_KEY, JSON.stringify(s)); } catch (e) {}
  }
  function _getPregLinkState(k) {
    var s = _loadPregLinkState();
    return s[k] || null;
  }
  function _setPregLinkState(k, patch) {
    var s = _loadPregLinkState();
    if (!s[k]) s[k] = {};
    for (var f in patch) { if (patch.hasOwnProperty(f)) s[k][f] = patch[f]; }
    _savePregLinkState(s);
  }

  /* ═══ 判断是否是"高危"怀孕（有配偶/恋人时） ═══ */
  function _getPregnancyContext() {
    var rel = _loadRelations();
    var pregState = _v('user.健康.怀孕状态', '无');
    return {
      spouse: rel.spouse || null,
      affairs: rel.affairs || [],
      hasPartner: !!(rel.spouse || (rel.affairs && rel.affairs.length > 0)),
      pregnancyState: pregState
    };
  }

  /* ═══ 检测避孕失败（已婚时失败率 +20%） ═══ */
  function _calcConceptionChance() {
    var rel = _loadRelations();
    var contracept = _v('user.健康.避孕', false);
    var baseChance = contracept ? 0.05 : 0.35;  /* 避孕 = 5%，无避孕 = 35% */

    /* 已婚：避孕失败率提升 20% */
    if (rel.spouse) {
      baseChance = contracept ? 0.25 : 0.55;
    }
    /* 有恋爱对象：小幅提升 */
    else if (rel.affairs && rel.affairs.length > 0) {
      baseChance = contracept ? 0.15 : 0.45;
    }

    return baseChance;
  }

