    d += '<div style="font-size:10px;color:' + t.textDim + ';line-height:1.9;padding:12px;background:rgba(255,120,180,.08);border-radius:10px;border:1px solid rgba(255,120,180,.25);margin-bottom:12px;white-space:pre-wrap">';
    d += '验孕棒显示两条杠。<br>';
    if (ctx.spouse) d += '你的配偶是：<b>' + _esc(ctx.spouse) + '</b>。';
    else if (ctx.affairs && ctx.affairs.length) d += '你的恋爱对象：<b>' + ctx.affairs.map(_esc).join('、') + '</b>。';
    else d += '你没有配偶，也没有恋人。';
    d += '<br><br>你打算怎么做？';
    d += '</div>';

    d += '<div style="display:flex;flex-direction:column;gap:6px">';

    /* 选项：告诉对方 */
    if (ctx.hasPartner) {
      var tellTarget = ctx.spouse || (ctx.affairs && ctx.affairs[0]) || '';
      d += '<div class="av-preg-opt" data-act="tell" style="padding:12px;border-radius:10px;cursor:pointer;background:rgba(80,200,120,.1);border:1px solid rgba(80,200,120,.3)">';
      d += '<div style="font-size:11px;font-weight:600;color:#50c878">💬 告诉' + _esc(tellTarget) + '</div>';
      d += '<div style="font-size:8px;color:' + t.textMuted + ';margin-top:2px">' + ta_word(tellTarget) + '可能会有反应，你们共同面对</div>';
      d += '</div>';
    }

