    d += '<div class="av-preg-opt" data-act="hide" style="padding:12px;border-radius:10px;cursor:pointer;background:rgba(255,176,96,.1);border:1px solid rgba(255,176,96,.3)">';
    d += '<div style="font-size:11px;font-weight:600;color:#ffb060">🤫 先隐瞒</div>';
    d += '<div style="font-size:8px;color:' + t.textMuted + ';margin-top:2px">压力 +20，风险：被对方发现</div>';
    d += '</div>';

    /* 选项：单独处理 */
    d += '<div class="av-preg-opt" data-act="alone" style="padding:12px;border-radius:10px;cursor:pointer;background:rgba(160,160,160,.1);border:1px solid rgba(160,160,160,.3)">';
    d += '<div style="font-size:11px;font-weight:600;color:' + t.textDim + '">🚶 一个人处理</div>';
    d += '<div style="font-size:8px;color:' + t.textMuted + ';margin-top:2px">压力 +30，人气 -10</div>';
    d += '</div>';

    d += '</div>';

    var w = _dialog(d);
    w.find('.av-preg-opt').on('click', function() {
      var act = $(this).data('act');
      w.remove();
      _handlePregnancyDecision(act);
    });
