  /* ═══ 处理玩家的怀孕决定 ═══ */
  function _handlePregnancyDecision(act) {
    var ctx = _getPregnancyContext();
    var curWeek = _v('user.当前时间.周数', 1);

    /* 记状态 */
    _setPregLinkState('current', {
      decision: act,
      decisionWeek: curWeek,
      spouse: ctx.spouse,
      affairs: ctx.affairs
    });

    if (act === 'tell') {
      var target = ctx.spouse || (ctx.affairs && ctx.affairs[0]) || '';
      if (typeof triggerSlash === 'function') {
        var msg = '【怀孕 · 告诉对方】\n' +
          '我确认怀孕了，我决定告诉' + target + '。\n' +
          '请根据' + target + '的性格（' + ta_word(target) + '）和我们当前的关系阶段，演绎' + target + '得知消息后的反应：\n' +
          '1. 是惊喜、惊吓、还是其他情绪？\n' +
          '2. ' + ta_word(target) + '会问什么？会怎么说？\n' +
          '3. 你们会一起决定生还是堕吗？\n' +
          '之后请让我再次做出"留下孩子 / 终止妊娠"的最终决定。\n';

        var co = _getActorCompany(target);
        if (co && co !== '未知') msg += '本次对话后更新 艺人.' + co + '.' + target + '.好感度 +10（' + ta_word(target) + '接受了这件事）或 -20（' + ta_word(target) + '无法接受）。\n';
        triggerSlash('/send ' + msg + ' | /trigger');
      }
      return;
    }

    if (act === 'hide') {
      if (typeof triggerSlash === 'function') {
        triggerSlash('/send 【怀孕 · 隐瞒】我确认怀孕了，但决定先隐瞒这件事。请演绎我独自面对的身体变化、心理压力，以及日常里努力掩饰的过程。压力 +20。如果剧情中出现可能被配偶/恋人发现的场景（比如一起洗澡、同床、体检等），请判断是否被发现。 | /trigger');
      }
      return;
    }

    if (act === 'alone') {
      if (typeof triggerSlash === 'function') {
        triggerSlash('/send 【怀孕 · 一个人处理】我确认怀孕了，没有告诉任何人，决定一个人面对。请演绎这段孤独的时期，以及我做出的下一步决定（留下还是终止）。压力 +30，人气 -10。 | /trigger');
      }
      return;
    }
  }

  /* ═══ 检测是否到了"孩子出生"的时间 ═══ */
  function _checkPregBirth() {
    var pregState = _v('user.健康.怀孕状态', '无');
    if (pregState !== '已处理') return;

    var linkState = _loadPregLinkState();
    var cur = linkState.current;
    if (!cur) return;
    if (cur.birthed) return;
    if (cur.decision === 'abort') return;  /* 已经终止 */

    var curWeek = _v('user.当前时间.周数', 1);
    var decideWeek = cur.decisionWeek || curWeek;

    /* 怀孕周期约 36 周（9 个月）；如果是一年内循环，用 36 周 */
    var expectedBirthWeek = decideWeek + 36;
    if (curWeek < expectedBirthWeek) return;

    /* 到了，触发生产事件 */
    _setPregLinkState('current', { birthed: true, birthWeek: curWeek });

    setTimeout(function() {
      _showBirthEvent(cur);
    }, 2500);
  }

