    d += '<div style="font-size:11px;font-weight:600;color:' + t.textDim + '">⏭️ 略过细节</div>';
    d += '<div style="font-size:8px;color:' + t.textMuted + ';margin-top:2px">只更新状态，不演绎</div>';
