  /* ═══ 生产前后的"事业暂停"提示 ═══ */
  function _checkPregWorkBan() {
    var pregState = _v('user.健康.怀孕状态', '无');
    var linkState = _loadPregLinkState();
    var cur = linkState.current;
    if (!cur || cur.birthed) return;

    var curWeek = _v('user.当前时间.周数', 1);
    var decideWeek = cur.decisionWeek || curWeek;

    /* 已确认怀孕到生产前，都禁止接本 */
    if (pregState === '已确认' || (pregState === '已处理' && curWeek >= decideWeek)) {
      /* 只在第一次拦截时弹一次提示 */
      var notifiedKey = 'av-preg-workban-notified-' + decideWeek;
      try {
        if (localStorage.getItem(notifiedKey)) return;
        localStorage.setItem(notifiedKey, '1');
      } catch (e) {}

      setTimeout(function() {
        if (typeof triggerSlash === 'function') triggerSlash('/echo severity:warning 你已确认怀孕，怀孕期间无法接新剧本。');
      }, 500);
    }
  }

  /* ═══ 周结算检查入口 ═══ */
  function _checkPregnancyWeekly() {
    var curWeek = _v('user.当前时间.周数', 1);
    var lastCheck = 0;
    try { lastCheck = parseInt(localStorage.getItem(PREG_CHECK_KEY) || '0'); } catch (e) {}
    if (lastCheck >= curWeek) return;
    try { localStorage.setItem(PREG_CHECK_KEY, String(curWeek)); } catch (e) {}

    _checkPregBirth();
    _checkPregWorkBan();
  }

