  /* ═══ ① AI 判定挖角成功率 ═══ */
  function _calcPoachChance(actorName, fromCo, toCo) {
    var favor = _getCharFavor(actorName);
    var actorLevel = _v('艺人.' + fromCo + '.' + actorName + '.等级', 'F级');
    var actorLi = LEVEL_ORDER.indexOf(actorLevel);
    var myLevel = _v('user.等级', 'F级');
    var myLi = LEVEL_ORDER.indexOf(myLevel);
    var myFame = _v('user.名气', 0);
    var myCo = _v('user.当前签约公司', '未签约');

    /* 基础分：好感度占比最大 */
    var score = 0;
    score += Math.min(60, favor * 0.6);           /* 好感 0~60 */
    score += Math.min(20, myFame * 0.2);          /* 名气 0~20 */

    /* 等级差：公司等级 = 艺人池平均等级 */
    var fromCoLevel = 0, toCoLevel = 0;
    if (COMPANIES[fromCo] && COMPANIES[fromCo].actors.length) {
      var sum = 0, cnt = 0;
      for (var i = 0; i < COMPANIES[fromCo].actors.length; i++) {
        var lv = _v('艺人.' + fromCo + '.' + COMPANIES[fromCo].actors[i] + '.等级', 'F级');
        sum += LEVEL_ORDER.indexOf(lv); cnt++;
      }
      fromCoLevel = cnt ? (sum / cnt) : 0;
    }
    if (COMPANIES[myCo] && COMPANIES[myCo].actors.length) {
      var sum2 = 0, cnt2 = 0;
      for (var j = 0; j < COMPANIES[myCo].actors.length; j++) {
        var lv2 = _v('艺人.' + myCo + '.' + COMPANIES[myCo].actors[j] + '.等级', 'F级');
        sum2 += LEVEL_ORDER.indexOf(lv2); cnt2++;
      }
      toCoLevel = cnt2 ? (sum2 / cnt2) : 0;
    }

    var coGap = toCoLevel - fromCoLevel;
    if (coGap > 0) score += Math.min(15, coGap * 5);       /* 公司更好：+ */
    else if (coGap < 0) score -= Math.min(20, Math.abs(coGap) * 5);  /* 公司更差：- */

    /* 经纪人态度影响 */
    var mgrSigned = _v('经纪人.是否签约', false);
    if (mgrSigned) {
      var mgrFavor = _v('经纪人.好感度', 0);
      score += Math.min(10, mgrFavor * 0.1);
    }

    /* 演员自身状态 */
    var actorStatus = _v('艺人.' + fromCo + '.' + actorName + '.状态', '正常');
    if (actorStatus === '负面缠身') score += 15;   /* 落魄的艺人更好挖 */
    if (actorStatus === '沉寂') score += 10;
    if (actorStatus === '当红') score -= 20;       /* 当红的很难挖 */

    /* 上限/下限 */
    if (score > 85) score = 85;
    if (score < 5) score = 5;

    return Math.round(score);
  }

  /* ═══ 升级版挖角弹窗（替换原有"确定要挖"确认框） ═══ */
  function _showPoachDialog(actorName, fromCo) {
    var t = _t();
    var myCo = _v('user.当前签约公司', '未签约');
    if (myCo === '未签约') {
      if (typeof triggerSlash === 'function') triggerSlash('/echo severity=warning 你还没签约公司，无法挖人');
      return;
    }
    if (myCo === fromCo) {
      if (typeof triggerSlash === 'function') triggerSlash('/echo severity=warning 他已经是你的同事了');
      return;
    }

    var chance = _calcPoachChance(actorName, fromCo, myCo);
    var coins = _v('user.金币', 0);
    var cost = chance >= 60 ? 50000 : (chance >= 30 ? 20000 : 10000);  /* 违约金 */
    var canPay = coins >= cost;

    var d = '';
    d += '<div class="av-dlg-h">💼 挖角</div>';
    d += '<div style="font-size:10px;color:' + t.textDim + ';line-height:1.7;margin:8px 0;padding:10px;background:' + t.surfaceHover + ';border-radius:10px">';
    d += '目标：<b>' + _esc(actorName) + '</b>（' + _esc(fromCo) + '）<br>';
    d += '目标公司：<b>' + _esc(myCo) + '</b>';
    d += '</div>';

    /* 成功率展示 */
    d += '<div style="background:rgba(' + t.primaryRgb + ',.08);border:1px solid rgba(' + t.primaryRgb + ',.25);border-radius:10px;padding:12px;margin-bottom:10px;text-align:center">';
    d += '<div style="font-size:8px;color:' + t.textMuted + ';margin-bottom:4px">预估成功率</div>';
    d += '<div style="font-size:28px;font-weight:900;color:' + (chance >= 60 ? '#50c878' : chance >= 30 ? '#ffb060' : '#ff6060') + ';letter-spacing:2px">' + chance + '%</div>';
    d += '<div style="font-size:8px;color:' + t.textMuted + ';margin-top:4px">受好感度、公司等级、艺人状态影响</div>';
    d += '</div>';

    /* 费用展示 */
    d += '<div style="background:rgba(255,176,96,.08);border:1px solid rgba(255,176,96,.25);border-radius:10px;padding:10px;margin-bottom:10px;font-size:9px">';
    d += '<div style="display:flex;justify-content:space-between"><span style="color:' + t.textDim + '">违约金</span><span style="color:' + (canPay ? '#ffb060' : t.fail) + ';font-weight:600">💰' + cost + '</span></div>';
    d += '<div style="display:flex;justify-content:space-between;margin-top:4px"><span style="color:' + t.textDim + '">当前余额</span><span style="color:' + t.text + '">💰' + coins + '</span></div>';
    d += '</div>';

    d += '<div class="av-dlg-actions">';
    d += '<button class="av-dlg-btn av-dlg-cancel" id="av-poach-no">取消</button>';
    d += '<button class="av-dlg-btn av-dlg-ok" id="av-poach-yes"' + (canPay ? '' : ' disabled style="opacity:.5;cursor:not-allowed"') + '>' + (canPay ? '💼 尝试挖角' : '💰 金币不足') + '</button>';
    d += '</div>';

    var w = _dialog(d);
    w.find('#av-poach-no').on('click', function() { w.remove(); });
    w.find('#av-poach-yes').on('click', function() {
      if (!canPay) return;
      w.remove();
      _executePoach(actorName, fromCo, myCo, chance, cost);
    });
  }

  /* 执行挖角（掷骰判定） */
  function _executePoach(actorName, fromCo, toCo, chance, cost) {
    var curWeek = _v('user.当前时间.周数', 1);
    var roll = Math.floor(Math.random() * 100);
    var success = roll < chance;

    /* 记录 */
    var st = _loadPoachState();
    st.history = st.history || [];
    st.history.push({
      actor: actorName,
      fromCo: fromCo,
      toCo: toCo,
      week: curWeek,
      success: success,
      chance: chance
    });
    if (success) {
      /* 安排 2 周后原公司反击 */
      st.pendingRetaliate = st.pendingRetaliate || [];
      st.pendingRetaliate.push({
        actor: actorName,
        fromCo: fromCo,
        week: curWeek + 2,
        fired: false
      });
    }
    _savePoachState(st);

    if (typeof triggerSlash === 'function') {
      if (success) {
        triggerSlash('/send 【挖角成功】我成功把' + fromCo + '的' + actorName + '挖到了' + toCo + '，支付违约金' + cost + '金币。请演绎这场挖角的过程：和' + actorName + '的沟通、' + fromCo + '的反应、跳槽后的新环境。同时更新 艺人.' + fromCo + '.' + actorName + '.当前公司 为 ' + toCo + '，并从' + fromCo + '的旗下艺人列表中移除，加入' + toCo + '。user.金币 扣' + cost + '。 | /trigger');
      } else {
        triggerSlash('/send 【挖角失败】我试图把' + fromCo + '的' + actorName + '挖到' + toCo + '，但失败了。请演绎这次挖角的过程：' + actorName + '或' + fromCo + '的反应（可能' + actorName + '拒绝、可能' + fromCo + '察觉后加大挽留、可能消息走漏）。user.金币 仍扣一半（' + Math.floor(cost / 2) + '）作为尝试成本。 | /trigger');
      }
    }
  }

  /* ═══ ② 原公司反击事件（跳槽成功后 2 周触发） ═══ */
  function _checkPoachRetaliate() {
    if ($('.av-dlg-mask').length) return;
    if (typeof ScenePlayer !== 'undefined' && (ScenePlayer.state.active || ScenePlayer.state.waiting)) return;

    var curWeek = _v('user.当前时间.周数', 1);
    var st = _loadPoachState();
    if (!st.pendingRetaliate || !st.pendingRetaliate.length) return;

    var todo = null;
    for (var i = 0; i < st.pendingRetaliate.length; i++) {
      var p = st.pendingRetaliate[i];
      if (!p.fired && curWeek >= p.week) { todo = p; break; }
    }
    if (!todo) return;

    todo.fired = true;
    _savePoachState(st);

    setTimeout(function() {
      _showPoachRetaliateDialog(todo);
    }, 2000);
  }

