  function _handlePoachRetaliate(act, info, picked) {
    var actorName = info.actor;
    var fromCo = info.fromCo;
    var toCo = _v('user.当前签约公司', '未签约');

    if (act === 'counter') {
      if (typeof triggerSlash === 'function') {
        triggerSlash('/send 【原公司反击 · 正面回击】' + fromCo + '因为' + actorName + '的跳槽对我发起了「' + picked.label + '」反击。我决定正面反击。请演绎这场行业战：我方的应对、对方公司的反应、业界风向。扣 user.金币 20000（公关和情报费用），user.八卦值 +10，user.人气 可能波动。 | /trigger');
      }
      return;
    }
    if (act === 'endure') {
      if (typeof triggerSlash === 'function') {
        triggerSlash('/send 【原公司反击 · 忍耐】' + fromCo + '因为' + actorName + '的跳槽对我发起「' + picked.label + '」反击。我选择忍耐不回应。请演绎这次被打击的过程：' + actorName + '的名气/人气受损，我的资源被卡。user.人气 -8，user.名气 -3，' + actorName + '好感 +5（因为看到我为了保护他而受损失）。 | /trigger');
      }
      return;
    }
    if (act === 'compensate') {
      var coins = _v('user.金币', 0);
      if (coins < 30000) {
        if (typeof triggerSlash === 'function') triggerSlash('/echo severity=warning 金币不足，需要💰30000');
        return;
      }
      var success = Math.random() < 0.7;
      if (typeof triggerSlash === 'function') {
        if (success) {
          triggerSlash('/send 【原公司反击 · 私下和解】我花了 30000 金币私下和' + fromCo + '和解，事情一次性解决。请演绎这次私下会面的过程。user.金币 -30000，user.八卦值 +5（行业里都会知道这笔钱的意思）。 | /trigger');
        } else {
          triggerSlash('/send 【原公司反击 · 和解失败】我试图花 30000 金币和' + fromCo + '和解，但对方拿了钱还是继续搞事！请演绎这场翻车。user.金币 -30000，user.八卦值 +15，user.人气 -5。 | /trigger');
        }
      }
      return;
    }
  }

  /* ═══ ③ 玩家被挖角（人气≥60 且等级≥C） ═══ */
  function _checkPlayerPoach() {
    if ($('.av-dlg-mask').length) return;
    if (typeof ScenePlayer !== 'undefined' && (ScenePlayer.state.active || ScenePlayer.state.waiting)) return;
    if (typeof _getCurScr === 'function' && _getCurScr()) return;

    var curWeek = _v('user.当前时间.周数', 1);
    var st = _loadPoachState();
    if (st.playerPoachCooldown > 0 && (curWeek - st.playerPoachCooldown) < 4) return;

    var myFame = _v('user.名气', 0);
    var myLevel = _v('user.等级', 'F级');
    var myCo = _v('user.当前签约公司', '未签约');

    if (myFame < 60) return;
    if (LEVEL_ORDER.indexOf(myLevel) < 2) return;  /* 需要 ≥C 级 */
    if (myCo === '未签约') return;

    /* 20% 概率触发 */
    if (Math.random() > 0.20) return;

    st.playerPoachCooldown = curWeek;
    _savePoachState(st);

    setTimeout(function() {
      _showPlayerPoachDialog(myCo);
    }, 2000);
  }

