  /* 读取求婚状态 */
  function _loadProposalState() {
    try {
      var r = localStorage.getItem(PROPOSAL_KEY);
      if (r) return JSON.parse(r);
    } catch (e) {}
    return {};
  }

  /* 写入求婚状态 */
  function _saveProposalState(state) {
    try {
      localStorage.setItem(PROPOSAL_KEY, JSON.stringify(state));
    } catch (e) {}
  }

  /* 获取单个角色的求婚状态 */
  function _getProposalState(name) {
    var s = _loadProposalState();
    return s[name] || { triggered: false, triggeredWeek: 0, postponed: 0, missed: false };
  }

  /* 更新单个角色的求婚状态 */
  function _setProposalState(name, patch) {
    var s = _loadProposalState();
    if (!s[name]) s[name] = { triggered: false, triggeredWeek: 0, postponed: 0, missed: false };
    for (var k in patch) {
      if (patch.hasOwnProperty(k)) s[name][k] = patch[k];
    }
    _saveProposalState(s);
  }

  /* 检查求婚全局冷却 */
  function _checkProposalCooldown(curWeek) {
    var last = 0;
    try { last = parseInt(localStorage.getItem(PROPOSAL_COOLDOWN_KEY) || '0'); } catch (e) {}
    if (last > 0 && (curWeek - last) < 4) return false;
    return true;
  }
  function _markProposalCooldown(curWeek) {
    try { localStorage.setItem(PROPOSAL_COOLDOWN_KEY, String(curWeek)); } catch (e) {}
  }

  /* 检查是否有角色满足求婚条件 */
  function _getProposalCandidate() {
    if (typeof ScenePlayer !== 'undefined' && (ScenePlayer.state.active || ScenePlayer.state.waiting)) return null;
    if (typeof _getCurScr === 'function' && _getCurScr()) return null;

    var curWeek = _v('user.当前时间.周数', 1);
    var state = _loadProposalState();
    var confessionState = _loadConfessionState();
    var candidates = [];

    /* 检查某个角色是否已告白（必须先告白过才能求婚） */
    function hasConfessed(name) {
      var cs = confessionState[name];
      return cs && cs.triggered;
    }

    /* ═══ 1. 艺人 ═══ */
    for (var i = 0; i < ALL_ACTORS.length; i++) {
      var an = ALL_ACTORS[i];
      var co = _getActorCompany(an);
      if (!co || co === '未知') continue;

      var favor = _v('艺人.' + co + '.' + an + '.好感度', 0);
      if (favor < 80 || favor >= 90) continue;   /* 80~89 求婚 */
      if (!hasConfessed(an)) continue;           /* 必须已告白 */

      var st = state[an] || { triggered: false, triggeredWeek: 0, postponed: 0, missed: false };
      if (st.triggered || st.missed) continue;
      if (st.triggeredWeek > 0 && (curWeek - st.triggeredWeek) < 3) continue;
      if (!PROPOSAL_PLACES[an]) continue;

      candidates.push({
        name: an, type: 'actor', company: co,
        favor: favor, place: PROPOSAL_PLACES[an]
      });
    }

    /* ═══ 2. 经纪人 ═══ */
    var mgrName = _v('经纪人.姓名', '待选择');
    var mgrSigned = _v('经纪人.是否签约', false);
    if (mgrSigned && mgrName && mgrName !== '待选择') {
      var mFavor = _v('经纪人.好感度', 0);
      if (mFavor >= 80 && mFavor < 90 && hasConfessed(mgrName)) {
        var mSt = state[mgrName] || { triggered: false, triggeredWeek: 0, postponed: 0, missed: false };
        if (!mSt.triggered && !mSt.missed &&
            (mSt.triggeredWeek === 0 || (curWeek - mSt.triggeredWeek) >= 3) &&
            PROPOSAL_PLACES[mgrName]) {
          candidates.push({
            name: mgrName, type: 'manager',
            company: _v('经纪人.原公司', '独立'),
            favor: mFavor, place: PROPOSAL_PLACES[mgrName]
          });
        }
      }
    }

    /* ═══ 3. 老板 ═══ */
    for (var bossCo in _BOSSES) {
      if (!_BOSSES.hasOwnProperty(bossCo)) continue;
      var boss = _BOSSES[bossCo];
      if (!boss || !boss.name) continue;

      var bFavor = _v('老板.' + boss.name + '.好感度', 0);
      if (bFavor < 80 || bFavor >= 90) continue;
      if (!hasConfessed(boss.name)) continue;

      var bSt = state[boss.name] || { triggered: false, triggeredWeek: 0, postponed: 0, missed: false };
      if (bSt.triggered || bSt.missed) continue;
      if (bSt.triggeredWeek > 0 && (curWeek - bSt.triggeredWeek) < 3) continue;
      if (!PROPOSAL_PLACES[boss.name]) continue;

      candidates.push({
        name: boss.name, type: 'boss',
        company: bossCo, favor: bFavor, place: PROPOSAL_PLACES[boss.name]
      });
    }

    if (!candidates.length) return null;

    /* 好感优先，同好感艺人 > 经纪人 > 老板 */
    var typePriority = { 'actor': 0, 'manager': 1, 'boss': 2 };
    candidates.sort(function(a, b) {
      if (b.favor !== a.favor) return b.favor - a.favor;
      return (typePriority[a.type] || 0) - (typePriority[b.type] || 0);
    });
    return candidates[0];
  }

  /* 主入口 */
  function _checkProposal() {
    if ($('.av-dlg-mask').length) return;

    var curWeek = _v('user.当前时间.周数', 1);
    if (!_checkProposalCooldown(curWeek)) return;

    var cand = _getProposalCandidate();
    if (!cand) return;

    var st = _getProposalState(cand.name);
    if (st.postponed >= 3) {
      _setProposalState(cand.name, { missed: true });
      return;
    }

    setTimeout(function() {
      _showProposalDialog(cand.name, cand.place, cand.favor, cand.type);
    }, 1500);
  }

