  function _checkWeddingCooldown(curWeek) {
    var last = 0;
    try { last = parseInt(localStorage.getItem(WEDDING_COOLDOWN_KEY) || '0'); } catch (e) {}
    if (last > 0 && (curWeek - last) < 6) return false;
    return true;
  }
  function _markWeddingCooldown(curWeek) {
    try { localStorage.setItem(WEDDING_COOLDOWN_KEY, String(curWeek)); } catch (e) {}
  }

