  var BREAKUP_CHECK_KEY = 'av-breakup-last-week';

  function _checkBreakup() {
    if ($('.av-dlg-mask').length) return;
    if (typeof ScenePlayer !== 'undefined' && (ScenePlayer.state.active || ScenePlayer.state.waiting)) return;

    var curWeek = _v('user.当前时间.周数', 1);
    var last = 0;
    try { last = parseInt(localStorage.getItem(BREAKUP_CHECK_KEY) || '0'); } catch(e) {}
    if (last >= curWeek) return;
    try { localStorage.setItem(BREAKUP_CHECK_KEY, String(curWeek)); } catch(e) {}

    var rel = _loadRelations();

    /* ═══ 情况 A：已婚，配偶好感 <30 ═══ */
    if (rel.spouse) {
      var spouseFavor = 0;
      var co = _getActorCompany(rel.spouse);
      if (co && co !== '未知') {
        spouseFavor = _v('艺人.' + co + '.' + rel.spouse + '.好感度', 0);
      } else if (rel.spouse === _v('经纪人.姓名', '')) {
        spouseFavor = _v('经纪人.好感度', 0);
      } else {
        spouseFavor = _v('老板.' + rel.spouse + '.好感度', 0);
      }
      if (spouseFavor < 30) {
        setTimeout(function() {
          _showDivorceWarning(rel.spouse, spouseFavor);
        }, 2000);
        return;
      }
    }

    /* ═══ 情况 B：恋爱对象好感 <20 ═══ */
    for (var i = 0; i < rel.affairs.length; i++) {
      var an = rel.affairs[i];
      var favor = 0;
      var co2 = _getActorCompany(an);
      if (co2 && co2 !== '未知') {
        favor = _v('艺人.' + co2 + '.' + an + '.好感度', 0);
      } else if (an === _v('经纪人.姓名', '')) {
        favor = _v('经纪人.好感度', 0);
      } else {
        favor = _v('老板.' + an + '.好感度', 0);
      }
      if (favor < 20) {
        (function(actorName, actorFavor) {
          setTimeout(function() {
            _showBreakupWarning(actorName, actorFavor);
          }, 2000);
        })(an, favor);
        return;
      }
    }
  }

