    if (lastShowdown > 0 && (curWeek - lastShowdown) < 3) return;
    try { localStorage.setItem('av-showdown-last-week', String(curWeek)); } catch(e) {}

    /* 挑两个好感最高的 */
    highFavors.sort(function(a, b) { return b.favor - a.favor; });
